window.MUSEO = {"ramos":{"his":"Historia, Geografía y Cs. Sociales","len":"Lenguaje y Comunicación","mat":"Matemática","cie":"Ciencias Naturales","art":"Artes Visuales","tec":"Tecnología","mus":"Música","efi":"Educación Física y Salud"},"corto":{"his":"Historia","len":"Lenguaje","mat":"Matemática","cie":"Ciencias","art":"Artes","tec":"Tecnología","mus":"Música","efi":"Ed. Física"},"fases":["Investigar","Diseñar","Construir","Abrir el museo"],"salas":[{"nivel":1,"num":"Entrada","sala":"Así celebramos","periodo":"Hoy","pregunta":"¿Cómo celebramos en Chile?","hacen":"Pinturas de las fiestas de sus familias y de Chile, alrededor de un gran mapa del país pintado por el curso. Abren la inauguración cantando una canción de tradición oral con movimientos guiados.","inaug":"Abren el museo cantando en el escenario y llevan a sus familias a ver su pintura. No exponen ni memorizan textos.","equipos":"Todo el curso junto. Cada niño hace su propia pintura.","rol":"El escenario y la galería de la entrada.","ramos":{"his":90,"len":45,"art":90,"mus":45,"efi":45},"oa":"Historia OA 4, 5, 6, 8, 9 · Lenguaje OA 21, 23 · Artes OA 1–5 · Música OA 3, 4, 6 · Ed. Física OA 5"},{"nivel":3,"num":"Sala I","sala":"Chile en el mundo","periodo":"El planeta y la Antigüedad","pregunta":"¿Dónde está Chile en el mundo y qué heredamos de Grecia y Roma?","hacen":"Un gran planisferio con las zonas climáticas y Chile marcado, y fachadas de edificios chilenos con columnas y frontones heredados de Grecia y Roma (La Moneda, el ex Congreso Nacional, el Teatro Municipal).","inaug":"Reciben a los visitantes en la primera sala. Explican en parejas, en un minuto y con un guion con dibujos.","equipos":"Un equipo para el planisferio y tres o cuatro equipos de fachadas.","rol":"La primera sala del recorrido.","ramos":{"his":90,"len":45,"mat":45,"art":90,"tec":45},"oa":"Historia OA 1, 2, 4, 6, 7, 8 · Lenguaje OA 6, 9, 14, 17, 18, 28 · Matemática OA 14, 15, 16 · Artes OA 1, 3 · Tecnología OA 1–4"},{"nivel":7,"num":"Sala II","sala":"Antes de Chile","periodo":"Hace 14.500 años – siglo XV","pregunta":"¿Cómo vivieron los primeros habitantes de este territorio y cómo se adaptaron a su medio?","hacen":"Dioramas a escala de Monte Verde, la cultura Chinchorro, el pueblo diaguita, el Inca en Chile, los pueblos canoeros del sur y Rapa Nui. Además, las audioguías con código QR y las versiones accesibles del museo.","inaug":"Guían su sala con una exposición de dos minutos sin leer y apoyan con las audioguías.","equipos":"Seis equipos, uno por sitio o pueblo.","rol":"Equipo de accesibilidad: audioguías, letra grande y versión para niños pequeños.","ramos":{"his":90,"len":90,"mat":90,"art":90,"tec":45},"oa":"Historia OA 1, 2, 14, 15, 16, 21, 22 · Lengua y Literatura OA 13, 15, 22, 23, 24, 25 · Matemática OA 8 · Artes OA 2, 4 · Tecnología OA 1–5"},{"nivel":4,"num":"Sala III","sala":"América antes de Chile","periodo":"Siglos IV – XVI","pregunta":"¿Cómo eran las grandes civilizaciones americanas y cómo llegó el Inca hasta Chile?","hacen":"Dioramas en caja de Tikal, Tenochtitlan y Cusco, y un tramo del Qhapaq Ñan con un tambo y un chasqui, junto a un mapa de América.","inaug":"Guían su diorama con una explicación de inicio, desarrollo y cierre, apoyada en el guion.","equipos":"Cuatro equipos: maya, azteca, inca y el Qhapaq Ñan en Chile.","rol":"La sala de las civilizaciones americanas.","ramos":{"his":90,"len":90,"mat":45,"art":90,"tec":45},"oa":"Historia OA 1–6 · Lenguaje OA 6, 9, 13, 16, 17, 27, 28 · Matemática OA 16 · Artes OA 1, 2, 3 · Tecnología OA 1–4"},{"nivel":2,"num":"Sala IV","sala":"Pueblos originarios","periodo":"Período precolombino y hoy","pregunta":"¿Cómo vivían los pueblos originarios según el paisaje de su zona?","hacen":"Un mural-mapa de Chile con norte, centro y sur, y objetos modelados en greda o plasticina: viviendas, vasijas, canoas, tejidos. Cada objeto lleva una tarjeta de dos o tres oraciones.","inaug":"En parejas, presentan su objeto a las familias leyendo o diciendo su tarjeta.","equipos":"Cuatro equipos: aymara, diaguita, mapuche y un pueblo canoero del sur.","rol":"El mural de los pueblos.","ramos":{"his":90,"len":45,"art":90},"oa":"Historia OA 1, 2, 3, 8, 9, 10, 11 · Lenguaje OA 7, 10, 14, 15, 17, 27 · Artes OA 1, 3, 5"},{"nivel":5,"num":"Gran Sala","sala":"La Gran Maqueta","periodo":"El territorio y la Conquista","pregunta":"¿Cómo es Chile de norte a sur y qué pasó en cada zona cuando llegaron los europeos?","hacen":"La Gran Maqueta de Chile en cinco tramos (unos 4,3 m, 1 cm = 10 km), con relieve, ríos, lagos, glaciares y ciudades que se encienden con un circuito simple. Cada equipo hace además un diorama de la Conquista en su zona.","inaug":"La Gran Maqueta es el centro del museo. Guían su tramo y su diorama con una visita de dos minutos.","equipos":"Cinco equipos, uno por zona natural.","rol":"Constructores de la Gran Maqueta, la pieza central del museo.","ramos":{"his":90,"len":90,"mat":90,"cie":90,"art":90,"tec":45},"oa":"Historia OA 1, 2, 4, 7, 8, 9 · Lenguaje OA 7, 8, 11, 15, 17, 18, 28 · Matemática OA 19, 20 · Ciencias OA 9, 10, 12, 14 · Artes OA 1, 2, 3 · Tecnología OA 1–4"},{"nivel":8,"num":"Sala V","sala":"Colonia y frontera","periodo":"Siglos XVI – XVIII","pregunta":"¿Cómo era la sociedad colonial y cómo convivieron españoles, mestizos y mapuche en la frontera?","hacen":"Dioramas de la Plaza de Armas de Santiago, la iglesia de San Francisco, una hacienda, los fuertes de Valdivia, el Parlamento de Quilín y las misiones de Chiloé. Además, la curaduría de todo el museo: recorrido, señalética y montaje.","inaug":"Guían su sala y orientan a los visitantes por todo el museo.","equipos":"Seis equipos, uno por tema colonial.","rol":"Equipo curador: diseña el recorrido, la señalética y dirige el montaje.","ramos":{"his":90,"len":90,"mat":90,"art":90,"tec":45},"oa":"Historia OA 8, 11, 12, 13, 16, 17, 19 · Lengua y Literatura OA 14, 16, 23, 24, 25, 26 · Matemática OA 11 · Artes OA 2, 4, 6 · Tecnología OA 1–5"},{"nivel":6,"num":"Sala VI","sala":"La República","periodo":"1810 – siglo XX","pregunta":"¿Cómo se formó la República y por qué cada hecho ocurrió en su lugar?","hacen":"Dioramas de la Independencia, el ferrocarril, el salitre, la Araucanía, Fuerte Bulnes, Rapa Nui y el terremoto de Chillán, ligados a su región. Sobre la Gran Maqueta de 5.°, instalan la capa de regiones y capitales.","inaug":"Guían su sala con una visita de dos minutos sin leer. Como equipo de difusión, hicieron las invitaciones del museo.","equipos":"Siete u ocho equipos, uno por zona y momento.","rol":"Equipo de difusión: invitaciones y entradas del museo.","ramos":{"his":90,"len":90,"mat":90,"cie":90,"art":90,"tec":45},"oa":"Historia OA 2, 4, 5, 6, 10, 11, 12, 13, 14, 20, 21 · Lenguaje OA 7, 8, 11, 15, 17, 18, 27, 29 · Matemática OA 2, 3, 13, 18 · Ciencias OA 11, 13, 16, 17, 18 · Artes OA 1–5 · Tecnología OA 1, 2, 3, 4, 6, 7"}],"niveles":{"1":[{"r":"his","f":1,"min":45,"t":"¿Cómo celebramos en Chile?","oa":"Historia OA 5 · OA 6","obj":"Reconocer fiestas, conmemoraciones y símbolos que forman parte de la identidad de su comunidad y del país.","ini":[10,["Muestra cuatro fotos grandes: una ramada de Fiestas Patrias, una celebración de We Tripantu, una fiesta religiosa o de la comuna y una celebración familiar.","Pregunta: <i>¿Qué está pasando aquí? ¿Has estado en una fiesta así?</i>"]],"des":[25,["Conversa con el curso sentado en semicírculo: qué se come, qué se baila, qué se canta, qué ropa se usa en cada fiesta.","Presenta la bandera, el escudo y la canción nacional como símbolos que aparecen en las conmemoraciones.","Anuncia el desafío: <b>el curso va a pintar las fiestas de Chile para el museo del colegio y va a cantar en la inauguración.</b><span class=\"di\">Vamos a hacer la entrada del museo: lo primero que verán los visitantes serán sus pinturas.</span>"]],"cie":[10,["Cada niño dice en voz alta qué fiesta le gustaría pintar.","Entrega la Guía A1 para llevar a la casa: una pregunta para la familia sobre la fiesta que más celebran."]],"rec":["Fotos impresas o proyectadas de cuatro celebraciones","Bandera y escudo de Chile","Guía A1: Mi fiesta (para la casa)"],"ev":"<p>Formativa: observa quién reconoce al menos una fiesta y un símbolo patrio.</p>","prep":["Reunir cuatro fotos de celebraciones de distintos lugares de Chile."]},{"r":"his","f":1,"min":45,"t":"Chile en el mapa","oa":"Historia OA 8 · OA 9","obj":"Identificar Chile en un mapa, con la cordillera de los Andes, el océano Pacífico, su región y su localidad.","ini":[10,["Muestra un globo terráqueo y pregunta: <i>¿Dónde vivimos nosotros?</i> Ayuda a encontrar Chile."]],"des":[25,["En el suelo o en la pizarra, despliega el contorno grande de Chile que preparaste en papel kraft.","Pinten juntos de azul el océano y de café la cordillera; cada niño pinta un pedacito.","Marca con una estrella la región y la comuna donde está el colegio.<span class=\"di\">Este mapa va a ir en la entrada del museo y alrededor pondremos sus pinturas.</span>"]],"cie":[10,["Ronda: cada niño señala en el mapa la cordillera, el mar o la estrella del colegio."]],"rec":["Globo terráqueo","Contorno de Chile en papel kraft (unos 2 m)","Témperas azul y café, pinceles gruesos"],"ev":"<p>Formativa: cada niño ubica al menos un elemento en el mapa.</p>","prep":["Dibujar el contorno de Chile en papel kraft (proyectando un mapa sobre la pared y calcando)."]},{"r":"len","f":1,"min":45,"t":"Lo que me contaron en casa","oa":"Lenguaje OA 21 · OA 23 · Historia OA 4","obj":"Expresar oralmente lo que aprendieron en la familia sobre una fiesta, usando frases completas y escuchando a los demás.","ini":[5,["Recuerda las normas de la ronda: hablar de a uno, mirar a quien habla."]],"des":[30,["Cada niño trae la Guía A1 y cuenta en una o dos frases la fiesta que celebra su familia.","Ayuda con preguntas: <i>¿Qué comen? ¿Quiénes van? ¿Qué es lo que más te gusta?</i>","Anota en un papelógrafo las fiestas que aparecen; quedará en la sala para la clase de Artes."]],"cie":[10,["Conversen: <i>¿Qué fiestas se repiten? ¿Cuál no conocían?</i>"]],"rec":["Guía A1 completa","Papelógrafo y plumones"],"ev":"<p>Formativa con una lista simple: se expresa con una frase completa, respeta su turno.</p>","nota":"<p>Si un niño no trae la guía, invítalo a contar una fiesta del colegio. Nadie queda sin hablar por no traer la tarea.</p>"},{"r":"art","f":3,"min":90,"t":"Pintamos nuestra fiesta","oa":"Artes Visuales OA 1 · OA 2 · OA 3","obj":"Crear una pintura sobre una fiesta o celebración, a partir de la observación de su vida familiar y su comunidad.","ini":[15,["Muestra dos obras chilenas que retraten fiestas o costumbres (por ejemplo, una pintura de una fonda o una arpillera).","Pregunta: <i>¿Qué colores ven? ¿Qué personas aparecen? ¿Qué están haciendo?</i>"]],"des":[60,["Cada niño pinta en un medio pliego la fiesta que eligió: primero dibuja con lápiz grueso a las personas, después pinta con témpera.","Recorre las mesas y pregunta por los colores: cálidos para el sol y la fiesta, fríos para la noche o el invierno (OA 2).","Deja las pinturas secando en un lugar plano."]],"cie":[15,["Cada niño dicta al docente una frase para su cédula: <i>«Esta es la fiesta de…»</i>. Escríbela en una tarjeta."]],"rec":["Medio pliego de cartulina por niño","Témperas, pinceles gruesos, vasos y paños","Dos imágenes de obras chilenas","Tarjetas para las frases"],"ev":"<p>Formativa con la Guía A1 al reverso: la pintura muestra una celebración con personas y colores elegidos.</p>"},{"r":"mus","f":2,"min":45,"t":"Aprendemos una canción de nuestra tierra","oa":"Música OA 3 · OA 4","obj":"Escuchar una canción de tradición oral y cantarla al unísono, acompañándola con percusión simple.","ini":[10,["Escuchen dos canciones o rondas de tradición oral chilena. Pregunta cuál quieren cantar en la inauguración."]],"des":[25,["Enseña la canción elegida por frases: tú cantas, el curso repite.","Agrega percusión con palmas, panderos o instrumentos hechos con botellas y semillas."]],"cie":[10,["Canten la canción completa una vez, de pie."]],"rec":["Dos canciones de tradición oral chilena (audio)","Panderos o instrumentos de percusión hechos en la sala"],"ev":"<p>Formativa: participa cantando y marca el pulso.</p>","nota":"<p>Elige una canción corta, de no más de dos estrofas, y que se pueda cantar sin micrófono.</p>"},{"r":"efi","f":3,"min":45,"t":"Movimientos para la canción","oa":"Educación Física y Salud OA 5","obj":"Crear y ejecutar movimientos guiados que acompañen la canción, expresando emociones y siguiendo el ritmo.","ini":[10,["Calentamiento con juego de imitación: el docente se mueve y el curso lo sigue."]],"des":[25,["Con la canción de Música, propón cuatro movimientos simples (por ejemplo, girar con un pañuelo, aplaudir, avanzar, saludar).","Ensayen en ronda y luego en dos filas frente a un público imaginario."]],"cie":[10,["Vuelta a la calma y conversación: <i>¿Cómo se sintieron bailando juntos?</i>"]],"rec":["Canción en audio","Pañuelos (opcional)","Espacio amplio: gimnasio o patio"],"ev":"<p>Formativa: sigue la secuencia de movimientos con apoyo.</p>"},{"r":"art","f":4,"min":45,"t":"Nuestra galería","oa":"Artes Visuales OA 4 · OA 5","obj":"Observar las pinturas del curso y explicar qué les gusta de su obra y de la de un compañero.","ini":[10,["Pega las pinturas en la pared formando una galería."]],"des":[25,["Recorrido en parejas: cada niño elige una pintura que no es suya y dice qué le gusta (un color, una persona, un detalle).","Ubiquen juntos las pinturas alrededor del mapa grande de Chile, cerca del lugar donde se celebra cada fiesta."]],"cie":[10,["Cada niño dice qué le gusta de su propia pintura."]],"rec":["Pinturas secas","Mapa grande de Chile","Cinta de enmascarar"],"ev":"<p>Formativa: explica una preferencia usando un elemento visual (color, línea, forma).</p>"},{"r":"mus","f":4,"min":45,"t":"Ensayo general en el escenario","oa":"Música OA 6 · Educación Física OA 5","obj":"Presentar la canción con sus movimientos ante otro curso, como ensayo de la inauguración.","ini":[10,["Recuerda dónde se paran, cómo entran y cómo saludan al público."]],"des":[25,["Ensayo en el lugar de la inauguración: entrada, canción con movimientos, saludo final.","Si es posible, invita a un curso vecino como público de prueba."]],"cie":[10,["Conversen qué salió bien y qué hay que repetir."]],"rec":["Lugar de la inauguración","Canción en audio o instrumento de acompañamiento"],"ev":"<p>Formativa: presenta junto al grupo ante un público.</p>"},{"r":"his","f":4,"min":45,"t":"Inauguración: abrimos el museo","oa":"Historia OA 6 · Música OA 6","obj":"Participar en la inauguración del museo cantando y mostrando sus pinturas a sus familias.","ini":[10,["Revisa con el curso dónde está su galería y dónde está el escenario."]],"des":[25,["El curso abre la inauguración con su canción.","Después, cada niño lleva a su familia a ver su pintura en la galería y le muestra la estrella del colegio en el mapa."]],"cie":[10,["De vuelta en la sala: <i>¿Qué fue lo que más te gustó del museo?</i> Cada niño dibuja su momento favorito."]],"rec":["Galería montada","Escenario","Hojas para el dibujo final"],"ev":"<p>Formativa con el dibujo final. En este nivel no se califica una exposición oral.</p>","nota":"<p>En 1.° básico los niños no exponen ni memorizan textos: participan pintando, cantando y acompañando a sus familias. Eso es lo esperable para su edad.</p>"}],"2":[{"r":"his","f":1,"min":45,"t":"¿Quiénes vivían aquí antes?","oa":"Historia OA 1 · OA 10","obj":"Ubicar en un mapa de Chile las zonas donde vivían algunos pueblos originarios en el período precolombino.","ini":[10,["Muestra objetos o imágenes de pueblos originarios (una vasija diagüita, un tejido mapuche, una canoa de corteza). Pregunta quién los hizo y cuándo."]],"des":[25,["Con el mapa grande de Chile dividido en norte, centro y sur, pega las imágenes de cuatro pueblos: aymara (norte), diaguita (norte chico), mapuche (centro-sur) y yagán o kawésqar (extremo sur).","Forma cuatro equipos, uno por pueblo.<span class=\"di\">Cada equipo va a mostrar en el museo cómo vivía su pueblo: su casa, su comida o su ropa.</span>"]],"cie":[10,["Cada equipo repite el nombre de su pueblo y señala dónde vivía."]],"rec":["Mapa grande de Chile dividido en norte, centro y sur","Imágenes de los cuatro pueblos","Objetos o fotos de objetos"],"ev":"<p>Formativa: el equipo ubica a su pueblo en la zona correcta.</p>","prep":["Imprimir láminas de los cuatro pueblos (el Museo Chileno de Arte Precolombino publica imágenes para escolares)."]},{"r":"his","f":1,"min":90,"t":"Así vivían según su paisaje","oa":"Historia OA 1 · OA 8 · OA 11","obj":"Relacionar el paisaje donde vivía cada pueblo con los recursos que usaba para alimentarse, abrigarse y construir su vivienda.","ini":[15,["Muestra tres paisajes (desierto, valle, bosque lluvioso) y pregunta: <i>¿Con qué construirías tu casa aquí?</i>"]],"des":[60,["Estaciones con láminas: vivienda, alimentación y abrigo. Cada equipo rota por las tres estaciones mirando solo su pueblo.","En la Guía A2 dibujan lo que encontraron en cada estación y marcan el paisaje de su pueblo.","Cada equipo elige <b>qué objeto modelará</b> para el museo (una ruka, una vasija, una balsa, un tejido)."]],"cie":[15,["Cada equipo dice: «Nuestro pueblo vivía en… y usaba… para…»."]],"rec":["Láminas por estación","Guía A2: Mi pueblo y mi objeto"],"ev":"<p>Formativa con la Guía A2.</p>"},{"r":"len","f":2,"min":45,"t":"Buscamos dos datos","oa":"Lenguaje OA 7 · OA 10","obj":"Buscar información sobre su pueblo en un texto breve indicado por el docente y extraer dos datos.","ini":[10,["Lee en voz alta un texto informativo breve sobre un pueblo y muestra cómo se subraya un dato."]],"des":[25,["Cada equipo recibe un texto corto (media página, letra grande) sobre su pueblo.","Leen con apoyo y subrayan dos datos: dónde vivía y qué hacía con su objeto."]],"cie":[10,["Cada equipo comparte un dato en voz alta."]],"rec":["Un texto informativo breve por pueblo","Lápices de color para subrayar"],"ev":"<p>Formativa: extrae información explícita con apoyo.</p>"},{"r":"len","f":3,"min":45,"t":"La tarjeta del museo","oa":"Lenguaje OA 14 · OA 15 · OA 17","obj":"Escribir dos o tres oraciones informativas sobre el objeto, con mayúscula inicial y punto final.","ini":[10,["Muestra una tarjeta modelo: <i>«Esta es una ruka. Los mapuche la construían con paja y madera. Adentro cocinaban y conversaban.»</i>"]],"des":[25,["Con la Guía A3, cada pareja escribe su tarjeta usando los dos datos de la clase anterior.","Revisa: mayúscula al inicio, punto al final, letra clara."]],"cie":[10,["Cada pareja lee su tarjeta a otra pareja."]],"rec":["Guía A3: Tarjeta del museo","Tarjeta modelo"],"ev":"<p>Formativa: dos oraciones completas sobre el objeto, con mayúscula y punto.</p>"},{"r":"art","f":3,"min":90,"t":"Modelamos el objeto","oa":"Artes Visuales OA 1 · OA 3","obj":"Modelar un objeto de su pueblo con greda, plasticina o material reciclado, a partir de las láminas observadas.","ini":[15,["Muestra cómo se modela una vasija con la técnica de lulo (rollos de greda o plasticina)."]],"des":[60,["Cada equipo modela su objeto mirando las láminas: vivienda, vasija, balsa, telar o figura.","Pinta el fondo de su zona del mural-mapa: arena para el norte, verde para el centro, bosque y mar para el sur."]],"cie":[15,["Limpieza. Los objetos quedan secando con el nombre del equipo."]],"rec":["Greda o plasticina","Palitos, paja, lana, cartón","Témperas","Láminas de referencia"],"ev":"<p>Formativa: el objeto representa algo del modo de vida de su pueblo.</p>"},{"r":"art","f":4,"min":45,"t":"Montamos el mural de los pueblos","oa":"Artes Visuales OA 5 · Historia OA 9","obj":"Ubicar sus objetos en el mural-mapa y explicar qué les gusta de su trabajo y del de otro equipo.","ini":[10,["Recuerda dónde vivía cada pueblo en el mapa."]],"des":[25,["Cada equipo pega o ubica su objeto en su zona del mural, con su tarjeta al lado.","Recorrido: cada niño dice qué le gusta del objeto de otro equipo."]],"cie":[10,["Foto del mural terminado."]],"rec":["Mural-mapa","Objetos secos","Tarjetas"],"ev":"<p>Formativa: explica una preferencia usando un elemento visual.</p>"},{"r":"len","f":4,"min":45,"t":"Lo decimos en voz alta","oa":"Lenguaje OA 27","obj":"Decir en parejas la tarjeta de su objeto con volumen audible, mirando al público.","ini":[10,["Modela cómo se presenta un objeto: mirar al público, señalar el objeto, voz fuerte."]],"des":[25,["En parejas, practican decir su tarjeta frente al mural. Otra pareja escucha y dice si se escuchó bien."]],"cie":[10,["Ensayo general: cada pareja lo dice una vez frente al curso."]],"rec":["Mural montado","Tarjetas"],"ev":"<p>Formativa: dice dos oraciones con volumen audible. Puede leerlas de la tarjeta.</p>","nota":"<p>En 2.° básico no se espera que expliquen sin apoyo. Pueden leer su tarjeta o decirla con un compañero.</p>"},{"r":"his","f":4,"min":45,"t":"Inauguración: los pueblos de antes y de hoy","oa":"Historia OA 2 · OA 3","obj":"Presentar su objeto a las familias y comparar el modo de vida de los pueblos originarios en el pasado y hoy.","ini":[10,["Recuerda el turno de cada pareja frente al mural."]],"des":[25,["Durante la inauguración, cada pareja presenta su objeto a las familias que pasan.","Si llega un visitante de un pueblo originario, invítalo a contar cómo se vive hoy."]],"cie":[10,["De vuelta en la sala: <i>¿Qué cosas de estos pueblos seguimos usando hoy?</i> (palabras, comidas, tejidos)."]],"rec":["Mural-mapa montado","Pasaportes del museo"],"ev":"<p>Formativa: nombra una costumbre que se mantiene hasta hoy.</p>"}],"3":[{"r":"his","f":1,"min":45,"t":"¿Dónde está Chile en el mundo?","oa":"Historia OA 7","obj":"Distinguir en un globo y en un planisferio los hemisferios, la línea del Ecuador, los continentes y los océanos, y ubicar Chile.","ini":[10,["Pregunta: <i>Si hiciéramos un hoyo muy profundo desde el colegio, ¿dónde saldríamos?</i>"]],"des":[25,["Con el globo terráqueo, ubica la línea del Ecuador, los polos, los trópicos y los hemisferios.","Cada niño ubica Chile y responde: ¿en qué hemisferios está?, ¿qué océano lo baña?, ¿con qué continente se toca la Antártica chilena?"]],"cie":[10,["Presenta el desafío: <b>el curso construirá la sala «Chile en el mundo»: un gran planisferio y edificios de Chile que heredaron ideas de Grecia y Roma.</b>"]],"rec":["Globo terráqueo","Planisferio mural"],"ev":"<p>Formativa: ubica Chile y nombra un hemisferio y un océano.</p>"},{"r":"his","f":1,"min":90,"t":"Las zonas climáticas y cómo se vive en ellas","oa":"Historia OA 8","obj":"Identificar las zonas climáticas del mundo y explicar cómo las personas se adaptan a cada una, reconociendo las que atraviesa Chile.","ini":[15,["Muestra fotos de casas en distintos climas (una casa con techo en pendiente para la nieve, una vivienda en el desierto)."]],"des":[60,["Explica las zonas cálida, templada y fría en el planisferio.","En equipos, cada uno recibe una zona y busca en láminas cómo se viste, se construye y se alimenta la gente allí.","Marcan en un planisferio en blanco las zonas que atraviesa Chile, de norte a sur, incluida la Antártica."]],"cie":[15,["Cada equipo comparte una forma de adaptarse a su clima."]],"rec":["Planisferio en blanco por equipo","Láminas de paisajes y viviendas"],"ev":"<p>Formativa: relaciona un clima con una forma de adaptación.</p>"},{"r":"his","f":1,"min":45,"t":"Columnas griegas en nuestras calles","oa":"Historia OA 1 · OA 2","obj":"Reconocer el legado de Grecia y Roma en edificios de Chile, como las columnas, los frontones y los arcos.","ini":[10,["Muestra fotos de un templo griego y de La Moneda, el ex Congreso Nacional o el Teatro Municipal. Pregunta qué se parece."]],"des":[25,["Identifica columnas, frontones y arcos. Explica que muchos edificios públicos de Chile se inspiraron en Grecia y Roma.","Cada equipo elige un edificio chileno para construir su fachada."]],"cie":[10,["Cada equipo dice qué elemento griego o romano tiene su edificio."]],"rec":["Fotos de edificios de Chile y de templos griegos y romanos"],"ev":"<p>Formativa: identifica un elemento de la arquitectura clásica en un edificio chileno.</p>"},{"r":"len","f":1,"min":45,"t":"Buscamos información del edificio","oa":"Lenguaje OA 6 · OA 9","obj":"Buscar información sobre un edificio en libros o internet, usando títulos y subtítulos para encontrar datos.","ini":[10,["Muestra cómo se usa el índice o los subtítulos para encontrar un dato."]],"des":[25,["Cada equipo completa la Guía B1: nombre del edificio, ciudad, para qué se usa, qué elemento clásico tiene y un dibujo."]],"cie":[10,["Revisa que cada dato tenga su fuente anotada."]],"rec":["Guía B1: Ficha de investigación","Libros o computadores con sitios indicados"],"ev":"<p>Formativa con la Guía B1.</p>"},{"r":"mat","f":2,"min":45,"t":"De lo plano a lo 3D: la columna","oa":"Matemática OA 15 · OA 16","obj":"Construir figuras 3D (cilindro y paralelepípedo) a partir de sus redes, para las columnas y los cuerpos de las fachadas.","ini":[10,["Muestra un rollo de papel higiénico y una caja. Pregunta qué figura 3D son."]],"des":[25,["Cada niño recorta y arma la red de un cilindro (columna) y de un paralelepípedo (cuerpo del edificio).","Cuentan caras, aristas y vértices de cada figura."]],"cie":[10,["Cada equipo junta sus columnas: ¿cuántas necesita su fachada?"]],"rec":["Redes impresas de cilindro y paralelepípedo","Tijeras y pegamento"],"ev":"<p>Formativa: arma la figura desde la red y describe sus caras.</p>"},{"r":"mat","f":3,"min":45,"t":"¿Dónde va cada cosa en la sala?","oa":"Matemática OA 14 · Historia OA 6","obj":"Ubicar objetos en una cuadrícula para planificar dónde irá cada pieza de la sala «Chile en el mundo».","ini":[10,["Juego: ubicar objetos de la sala con coordenadas como en la batalla naval (A3, C5)."]],"des":[25,["Sobre una cuadrícula que representa la sala, cada equipo marca dónde irá su fachada y dónde el planisferio."]],"cie":[10,["Comparan planos: ¿hay lugar para que la gente camine?"]],"rec":["Cuadrícula impresa de la sala"],"ev":"<p>Formativa: describe la ubicación de un objeto con letra y número.</p>"},{"r":"tec","f":2,"min":45,"t":"Diseñamos la fachada","oa":"Tecnología OA 1 · OA 2","obj":"Diseñar la fachada del edificio y planificar sus pasos, materiales y medidas de seguridad.","ini":[10,["Muestra una fachada de cartón ya terminada como ejemplo."]],"des":[25,["Cada equipo dibuja a mano alzada su fachada y completa el plan de la Guía B2: pasos, materiales, herramientas y cuidado."]],"cie":[10,["Revisa y firma cada plan."]],"rec":["Guía B2: Plan de construcción"],"ev":"<p>Formativa con la Guía B2.</p>","alt":"art"},{"r":"art","f":3,"min":90,"t":"Construimos la sala","oa":"Artes Visuales OA 1 · OA 3 · Tecnología OA 3","obj":"Construir las fachadas y el planisferio con cartón, papel y materiales de reciclaje.","ini":[10,["Normas de seguridad con tijeras y pegamento."]],"des":[70,["Dos estaciones: <b>fachadas</b> (cuerpo de cartón, columnas de la clase de Matemática, frontón, color) y <b>planisferio</b> (pintar continentes, océanos y las zonas climáticas con colores distintos).","Ubican a Chile con una estrella grande en el planisferio."]],"cie":[10,["Limpieza y foto de avance."]],"rec":["Cartón, papel, témperas","Columnas armadas","Planisferio grande en papel kraft"],"ev":"<p>Formativa: la fachada muestra al menos un elemento clásico.</p>"},{"r":"tec","f":3,"min":45,"t":"Probamos y mejoramos","oa":"Tecnología OA 4","obj":"Probar la fachada con criterios de resistencia, terminaciones y seguridad, y mejorarla.","ini":[10,["Presenta tres criterios: se sostiene de pie, está bien terminada, no tiene puntas peligrosas."]],"des":[25,["Cada equipo prueba su fachada y la de otro equipo con los criterios. Anotan una mejora y la hacen."]],"cie":[10,["Comparten la mejora que hicieron."]],"rec":["Fachadas","Pegamento y cinta para reparar"],"ev":"<p>Evaluación del objeto con los tres criterios.</p>","alt":"art"},{"r":"len","f":3,"min":45,"t":"La cédula de nuestro edificio","oa":"Lenguaje OA 14 · OA 17 · OA 18","obj":"Escribir una cédula breve (40 a 60 palabras) sobre el edificio, organizada en dos párrafos.","ini":[10,["Lee una cédula modelo y marca sus dos partes: qué es y por qué tiene columnas."]],"des":[25,["Con la Guía B3, cada equipo escribe su cédula usando la ficha de investigación. Revisa mayúsculas, puntos y palabras repetidas."]],"cie":[10,["Pasan en limpio la versión final con letra grande."]],"rec":["Guía B3: Cédula corta","Cartulina"],"ev":"<p>Cédula final: dos párrafos con información correcta.</p>"},{"r":"len","f":4,"min":45,"t":"Ensayamos la explicación","oa":"Lenguaje OA 28","obj":"Explicar en un minuto el edificio a un público, con un inicio y un desarrollo, señalando la fachada.","ini":[10,["Muestra el guion con dibujos de la Guía B4: saludo, qué es, qué tiene de griego o romano."]],"des":[25,["Cada equipo ensaya frente a otro. El otro equipo levanta una tarjeta verde si se escuchó y se entendió."]],"cie":[10,["Ajustes finales."]],"rec":["Guía B4: Guion de un minuto","Tarjetas verdes"],"ev":"<p>Formativa: organiza la explicación en inicio y desarrollo, con apoyo del guion.</p>"},{"r":"his","f":4,"min":45,"t":"Inauguración: Chile en el mundo","oa":"Historia OA 4 · OA 7","obj":"Explicar a los visitantes dónde está Chile y qué heredamos de Grecia y Roma.","ini":[5,["Turnos de guía por pareja."]],"des":[30,["Los guías reciben a los visitantes en la primera sala del recorrido: muestran Chile en el planisferio y explican su fachada."]],"cie":[10,["De vuelta en la sala, cada niño completa la Guía B5 (autoevaluación con caritas)."]],"rec":["Sala montada","Guía B5: Autoevaluación"],"ev":"<p>Formativa con la Guía B5.</p>"}],"4":[{"r":"his","f":1,"min":90,"t":"Mayas, aztecas e incas","oa":"Historia OA 1 · OA 2 · OA 3 · OA 4","obj":"Comparar rasgos de las civilizaciones maya, azteca e inca, y organizar los equipos de la sala «América antes de Chile».","ini":[15,["Muestra tres imágenes: una pirámide maya, las chinampas de Tenochtitlan y Machu Picchu. Pregunta qué tienen en común."]],"des":[60,["Mini clase con un mapa de América: dónde vivía cada civilización y en qué paisaje.","Forma cuatro equipos: Tikal (maya), Tenochtitlan (azteca), Cusco (inca) y <b>el Qhapaq Ñan en Chile</b> (el camino inca que llegó hasta el valle central).","Cada equipo completa la primera parte de la Guía B1 con lo que ya saben."]],"cie":[15,["Cada equipo dice qué le gustaría mostrar en su diorama."]],"rec":["Mapa de América","Tres imágenes de las civilizaciones","Guía B1: Ficha de investigación"],"ev":"<p>Formativa con la Guía B1, parte 1.</p>"},{"r":"his","f":1,"min":45,"t":"El camino inca llega a Chile","oa":"Historia OA 3 · OA 6","obj":"Ubicar el Qhapaq Ñan en un mapa usando coordenadas y explicar para qué servía el sistema de caminos inca.","ini":[10,["Pregunta: <i>¿Cómo se enviaba un mensaje sin teléfono por un imperio enorme?</i> Presenta a los chasquis."]],"des":[25,["En un mapa con latitud y longitud, ubican Cusco, el camino hacia el sur y su llegada a Chile (valle de Copiapó y valle central).","Cada equipo registra un dato del camino en su Guía B1."]],"cie":[10,["Conversen: ¿qué caminos de Chile siguen hoy la ruta del Qhapaq Ñan?"]],"rec":["Mapa con latitud y longitud","Guía B1"],"ev":"<p>Formativa: ubica un lugar con coordenadas.</p>"},{"r":"len","f":1,"min":45,"t":"Buscar y clasificar información","oa":"Lenguaje OA 6 · OA 9","obj":"Buscar información sobre su civilización y clasificarla por temas (vivienda, alimentación, creencias, tecnología).","ini":[10,["Muestra cómo se usa el índice y los subtítulos de un libro informativo."]],"des":[25,["Cada equipo busca y clasifica información en la Guía B1, parte 2, con su fuente anotada."]],"cie":[10,["Revisa que haya al menos dos fuentes."]],"rec":["Guía B1, parte 2","Libros o sitios indicados"],"ev":"<p>Formativa: clasifica información por tema y anota fuentes.</p>"},{"r":"mat","f":2,"min":45,"t":"Las vistas de una pirámide","oa":"Matemática OA 16","obj":"Determinar las vistas frontal, lateral y superior de una figura 3D, para diseñar las construcciones del diorama.","ini":[10,["Muestra una pirámide de cartón desde tres lados."]],"des":[25,["Cada niño dibuja las tres vistas de una pirámide escalonada armada con cubos y luego de la construcción de su equipo."]],"cie":[10,["Comparan dibujos: ¿qué vista sirve para saber cuánto espacio ocupará en la caja?"]],"rec":["Cubos encajables","Hoja cuadriculada"],"ev":"<p>Formativa: dibuja correctamente las tres vistas.</p>"},{"r":"art","f":2,"min":45,"t":"El boceto del diorama","oa":"Artes Visuales OA 1 · OA 2","obj":"Diseñar el boceto del diorama a partir de la observación del arte y la arquitectura americanos.","ini":[10,["Muestra textiles y cerámicas mayas, aztecas e incas: colores y formas geométricas."]],"des":[25,["Cada equipo dibuja su escena: fondo, construcción principal y figuras. Eligen colores inspirados en el arte de su civilización."]],"cie":[10,["Galería de bocetos con comentarios."]],"rec":["Imágenes de arte americano","Hojas y lápices de colores"],"ev":"<p>Formativa: el boceto incluye fondo, construcción y figuras.</p>"},{"r":"tec","f":2,"min":45,"t":"Planificamos la construcción","oa":"Tecnología OA 1 · OA 2","obj":"Planificar la construcción del diorama: pasos, materiales, herramientas, seguridad e impacto ambiental de los materiales.","ini":[10,["Muestra un plan bien hecho y uno incompleto."]],"des":[25,["Cada equipo completa la Guía B2 y marca qué materiales son reciclados."]],"cie":[10,["Revisa y firma cada plan."]],"rec":["Guía B2: Plan de construcción"],"ev":"<p>Formativa con la Guía B2.</p>","alt":"art"},{"r":"art","f":3,"min":90,"t":"Construimos el diorama","oa":"Artes Visuales OA 3 · Tecnología OA 3","obj":"Construir el diorama en una caja con materiales de modelado y reciclaje, siguiendo el boceto y el plan.","ini":[10,["Normas de seguridad y organización por estaciones."]],"des":[70,["Estaciones: fondo pintado, construcción principal (pirámide, templo o tambo), figuras de plasticina y vegetación.","El equipo del Qhapaq Ñan construye un tramo de camino con un tambo y un chasqui."]],"cie":[10,["Limpieza y foto de avance."]],"rec":["Cajas de zapatos","Plasticina, cartón, palitos, témperas","Boceto y plan"],"ev":"<p>Formativa: el diorama sigue el boceto.</p>"},{"r":"tec","f":3,"min":45,"t":"Probamos y mejoramos el diorama","oa":"Tecnología OA 4","obj":"Evaluar la calidad del diorama con criterios técnicos, ambientales y de seguridad, y proponer mejoras.","ini":[10,["Presenta los criterios: firme, terminado, usa reciclaje, seguro."]],"des":[25,["Evaluación cruzada entre equipos y una mejora concreta por equipo."]],"cie":[10,["Comparten la mejora."]],"rec":["Dioramas","Pauta de criterios"],"ev":"<p>Evaluación del diorama con criterios.</p>","alt":"art"},{"r":"len","f":3,"min":90,"t":"Escribimos la cédula","oa":"Lenguaje OA 13 · OA 16 · OA 17","obj":"Escribir una cédula informativa de 60 a 80 palabras, con una idea central por párrafo y palabras propias.","ini":[15,["Lee la cédula modelo y marca: tema, idea de cada párrafo, fuente."]],"des":[60,["Planifican con la Guía B3: para quién escriben y qué quieren que entiendan.","Escriben el borrador, lo intercambian con otro equipo y corrigen con sus comentarios."]],"cie":[15,["Pasan en limpio la versión final."]],"rec":["Guía B3: Cédula corta","Cartulina"],"ev":"<p>Cédula final evaluada con la pauta de la Guía B3.</p>"},{"r":"len","f":4,"min":45,"t":"Ensayo de la visita","oa":"Lenguaje OA 27 · OA 28","obj":"Explicar el diorama con inicio, desarrollo y cierre, usando vocabulario nuevo y el diorama como apoyo.","ini":[10,["Modela una explicación corta con inicio, desarrollo y cierre."]],"des":[25,["Rondas de ensayo entre equipos con la Guía B4."]],"cie":[10,["Cada equipo anota una mejora."]],"rec":["Guía B4: Guion de un minuto"],"ev":"<p>Formativa: explica con estructura y sin leer todo el texto.</p>"},{"r":"his","f":4,"min":45,"t":"Inauguración: América antes de Chile","oa":"Historia OA 5","obj":"Presentar el diorama a los visitantes y reconocer la influencia de estas civilizaciones en los pueblos actuales.","ini":[5,["Turnos de guía."]],"des":[30,["Los guías reciben a los visitantes y explican su diorama."]],"cie":[10,["Reflexión: <i>¿Qué palabras, alimentos o costumbres de estas civilizaciones usamos hoy?</i> Guía B5."]],"rec":["Sala montada","Guía B5: Autoevaluación"],"ev":"<p>Formativa con la Guía B5.</p>"}],"5":[{"r":"his","f":1,"min":90,"t":"Lanzamiento: las cinco zonas de Chile","oa":"Historia OA 9","obj":"Caracterizar las grandes zonas naturales de Chile y organizar los equipos que construirán la Gran Maqueta.","ini":[15,["Proyecta fotos del Mundo Mágico original y de sus ruinas. Pregunta qué era y qué le pasó.","Cuenta que el curso construirá la pieza central del museo del colegio: <b>la Gran Maqueta de Chile</b>."]],"des":[60,["Presenta las cinco zonas naturales con fotos: Norte Grande, Norte Chico, Zona Central, Zona Sur y Zona Austral.","Sorteo de zonas: cada equipo recibe una zona. Completan el contrato de equipo (Guía 2).","Completan la parte A de la Guía 1: relieve, clima, vegetación y paisaje de su zona."]],"cie":[15,["Cada equipo dice en una oración qué hace única a su zona."]],"rec":["Fotos de las cinco zonas","Tarjetas de sorteo","Guías 1 y 2"],"ev":"<p>Formativa con el contrato de equipo y la parte A de la Guía 1.</p>","prep":["Imprimir tarjetas de sorteo con las cinco zonas.","Acordar con la coordinación dónde se armará la Gran Maqueta."]},{"r":"his","f":1,"min":90,"t":"La Conquista en nuestra zona","oa":"Historia OA 1 · OA 2 · OA 4 · OA 7","obj":"Investigar un hecho del descubrimiento o la conquista ocurrido en la zona del equipo, considerando a los pueblos que ya la habitaban.","ini":[15,["Pregunta: <i>Cuando llegaron los españoles, ¿el territorio estaba vacío?</i>"]],"des":[60,["Cada equipo investiga su hecho con el dossier: Norte Grande, el regreso de Almagro por el desierto (1537); Norte Chico, Almagro llega a Copiapó (1536); Zona Central, la fundación de Santiago (1541); Zona Sur, la batalla de Curalaba (1598); Zona Austral, Magallanes cruza el estrecho (1520).","Completan la parte B de la Guía 1: qué pasó, quiénes participaron, qué pueblos vivían ahí y qué les ocurrió."]],"cie":[15,["Cada equipo comparte la mirada del pueblo originario de su zona."]],"rec":["Dossier de fuentes por zona","Guía 1, parte B"],"ev":"<p>Formativa con la Guía 1, parte B.</p>"},{"r":"len","f":1,"min":90,"t":"Fuentes confiables","oa":"Lenguaje OA 7 · OA 8 · OA 11","obj":"Evaluar la confiabilidad de las fuentes del dossier y registrar con palabras propias las ideas principales.","ini":[15,["Compara un comentario anónimo de internet con la página de un museo. Construyan tres preguntas: ¿quién lo escribe?, ¿para qué?, ¿cuándo?"]],"des":[60,["Cada equipo evalúa sus fuentes en la tabla de la Guía 1.","Practican resumir un párrafo con palabras propias y completan lo que falta de la Guía 1."]],"cie":[15,["Firma las fichas que cumplen la lista de cotejo."]],"rec":["Guía 1","Dossier"],"ev":"<p>Lista de cotejo de la Guía 1 (entregable de la fase Investigar).</p>"},{"r":"cie","f":1,"min":90,"t":"El agua de nuestra zona","oa":"Ciencias Naturales OA 12 · OA 14","obj":"Describir la distribución del agua dulce y salada en la zona (ríos, lagos, glaciares, mar) y proponer cómo protegerla.","ini":[15,["Pregunta: <i>Si toda el agua del planeta cupiera en una botella de 1 litro, ¿cuánta sería agua dulce que podemos usar?</i> Muestra que es menos de una cucharadita."]],"des":[60,["Cada equipo identifica en su zona los ríos, lagos, glaciares y el mar (Guía 4A, parte 1).","Deciden cómo representar cada tipo de agua en el tramo: celofán azul para ríos y lagos, algodón o yeso para glaciares.","Proponen una acción para proteger el agua de su zona."]],"cie":[15,["Cada equipo comparte su acción de protección."]],"rec":["Atlas","Guía 4A: El agua y la luz de nuestra zona","Botella de 1 litro y cucharadita"],"ev":"<p>Formativa con la Guía 4A, parte 1.</p>"},{"r":"mat","f":2,"min":90,"t":"Del kilómetro al centímetro","oa":"Matemática OA 19 · OA 20","obj":"Convertir distancias reales en kilómetros a centímetros de la maqueta, usando la equivalencia 1 cm = 10 km, y medir el tramo.","ini":[15,["Plantea: <i>Chile mide unos 4.300 km de largo. ¿Cómo lo hacemos caber en el pasillo?</i> Presenta la regla del museo: 1 cm de maqueta = 10 km reales."]],"des":[60,["Practican conversiones: 100 km → 10 cm; 600 km → 60 cm; 1.000 km → 100 cm = 1 m.","Cada equipo calcula el largo de su tramo con la tabla de la Guía 3A y lo mide y marca sobre el cartón con huincha.","Suman los cinco tramos en la pizarra: deben dar cerca de 4,3 m."]],"cie":[15,["Si la suma no cuadra, buscan el error entre todos."]],"rec":["Guía 3A: Del kilómetro al centímetro","Huinchas de medir","Planchas de cartón"],"ev":"<p>Formativa con la Guía 3A (solucionario incluido).</p>"},{"r":"art","f":2,"min":90,"t":"Boceto del tramo y del diorama","oa":"Artes Visuales OA 1 · OA 2","obj":"Diseñar el paisaje del tramo y la escena del diorama a partir de la observación del paisaje chileno.","ini":[15,["Muestra pinturas de paisajes chilenos y cómo usan la luz y la sombra."]],"des":[60,["Cada equipo dibuja el tramo visto desde arriba (costa, cordillera, ríos, ciudades) y la escena del diorama de frente.","Eligen colores complementarios para destacar lo importante."]],"cie":[15,["Galería de bocetos y firma del docente."]],"rec":["Guía 5: Del boceto a la construcción","Imágenes de paisajes chilenos"],"ev":"<p>Formativa: boceto aprobado.</p>"},{"r":"tec","f":2,"min":45,"t":"Planificamos el tramo","oa":"Tecnología OA 1 · OA 2","obj":"Planificar la construcción del tramo: pasos, materiales, tiempos y cómo se unirá a los tramos vecinos.","ini":[10,["Presenta el problema: cinco tramos deben calzar en una sola maqueta que se pueda mover y guardar."]],"des":[25,["Cada equipo completa la Guía 5, parte C. Acuerdan con los equipos vecinos el ancho (50 cm) y cómo se unen."]],"cie":[10,["Revisa y firma cada plan."]],"rec":["Guía 5, parte C"],"ev":"<p>Formativa con la Guía 5, parte C.</p>","alt":"art"},{"r":"cie","f":3,"min":90,"t":"Una ciudad que se enciende","oa":"Ciencias Naturales OA 9 · OA 10","obj":"Construir un circuito eléctrico simple para iluminar una ciudad de la maqueta, distinguiendo conductores y aislantes.","ini":[15,["Muestra un circuito con pila, cable y ampolleta LED. Pregunta qué pasa si se corta el cable."]],"des":[60,["Cada equipo arma un circuito simple con interruptor de clip y lo prueba.","Prueban materiales para saber cuáles conducen (clip, papel aluminio) y cuáles aíslan (plástico, goma).","Instalan el circuito bajo el cartón para que la luz salga en la capital de su zona."]],"cie":[15,["Registran en la Guía 4A, parte 2, cómo funciona su circuito."]],"rec":["Pilas AA con portapilas","Ampolletas LED y cables","Clips, papel aluminio, plástico, goma","Guía 4A, parte 2"],"ev":"<p>Circuito funcionando y explicación en la Guía 4A.</p>","nota":"<p>Usa solo pilas, nunca corriente de la red. Revisa cada circuito antes de cerrarlo bajo el cartón.</p>"},{"r":"tec","f":3,"min":90,"t":"Construimos el tramo","oa":"Tecnología OA 3","obj":"Construir el tramo de la Gran Maqueta con relieve de papel maché, agua y ciudades, demostrando dominio de herramientas.","ini":[10,["Normas de seguridad con cartonero y tijeras."]],"des":[70,["Recortan la base al largo calculado, modelan la cordillera y la costa con papel maché, pintan, y ubican ríos, lagos, glaciares y ciudades."]],"cie":[10,["Limpieza; el tramo queda secando."]],"rec":["Planchas de cartón medidas","Papel maché, témperas","Celofán, algodón"],"ev":"<p>Formativa: el tramo sigue el plan y el largo calculado.</p>","alt":"art"},{"r":"art","f":3,"min":90,"t":"Construimos el diorama de la Conquista","oa":"Artes Visuales OA 3","obj":"Construir el diorama del hecho investigado con materiales de modelado y reciclaje, mostrando a los pueblos que habitaban la zona.","ini":[10,["Recuerda el boceto y la mirada del pueblo originario que debe aparecer."]],"des":[70,["Estaciones: fondo, relieve, figuras y detalles. Cada equipo construye su escena en una caja."]],"cie":[10,["Foto de avance."]],"rec":["Cajas","Plasticina, cartón, témperas"],"ev":"<p>Formativa: el diorama muestra el hecho y a los pueblos de la zona.</p>"},{"r":"len","f":3,"min":90,"t":"Escribimos la cédula","oa":"Lenguaje OA 15 · OA 17 · OA 18","obj":"Escribir y revisar una cédula informativa (80 a 100 palabras) sobre la zona y su hecho histórico, citando la fuente.","ini":[15,["Lee la cédula modelo de la Guía 6."]],"des":[60,["Planifican, escriben el borrador y lo revisan con la pauta de la Guía 6."]],"cie":[15,["Pasan en limpio la versión final."]],"rec":["Guía 6: Cédula de museo"],"ev":"<p>Cédula final evaluada con la pauta de la Guía 6.</p>"},{"r":"tec","f":4,"min":45,"t":"Unimos y probamos la Gran Maqueta","oa":"Tecnología OA 4","obj":"Unir los cinco tramos y evaluar si calzan, resisten y se pueden mover con seguridad.","ini":[10,["Llevan los tramos al lugar de montaje."]],"des":[25,["Unen los tramos de norte a sur: ¿continúan la costa y la cordillera? ¿Se encienden las ciudades? Cada equipo corrige lo que falle."]],"cie":[10,["Foto de la Gran Maqueta completa."]],"rec":["Los cinco tramos","Cinta de papel"],"ev":"<p>Evaluación del tramo con criterios de funcionamiento, terminación y seguridad.</p>","alt":"art"},{"r":"len","f":4,"min":45,"t":"Ensayo de la visita guiada","oa":"Lenguaje OA 28","obj":"Explicar el tramo y el diorama con introducción, desarrollo y cierre, sin leer.","ini":[10,["Modela una visita de dos minutos."]],"des":[25,["Rondas de ensayo con la Guía 7 y coevaluación con la Guía 9."]],"cie":[10,["Cada equipo anota dos mejoras."]],"rec":["Guías 7 y 9"],"ev":"<p>Formativa con la coevaluación.</p>"},{"r":"his","f":4,"min":90,"t":"Inauguración y reflexión","oa":"Historia OA 4 · OA 8","obj":"Guiar a los visitantes por la Gran Maqueta y reflexionar sobre el patrimonio y los efectos de la Conquista en los pueblos originarios.","ini":[15,["Montaje final y turnos de guía."]],"des":[60,["Inauguración: los guías explican su zona y su diorama. La Gran Maqueta es el centro del museo y la recorren todos los cursos."]],"cie":[15,["Reflexión escrita (Guía 10): <i>¿Qué cambió para los pueblos de mi zona con la llegada de los españoles? ¿Qué patrimonio colonial sigue presente?</i>"]],"rec":["Gran Maqueta y dioramas montados","Guía 10"],"ev":"<p>Sumativa con la rúbrica común: contenido histórico, relación zona–historia, construcción, cédula, visita guiada y trabajo en equipo.</p>"}],"6":[{"r":"his","f":1,"min":90,"t":"Lanzamiento: ¿qué Chile mostraba Mundo Mágico?","oa":"Historia OA 21 · OAH j (comparar puntos de vista)","obj":"Analizar cómo un parque representaba al país, identificando qué mostraba y qué dejaba fuera, y organizar los equipos del proyecto.","ini":[15,["Proyecta, sin decir de qué se trata, tres fotos del Mundo Mágico original (por ejemplo, la miniatura del Estadio Nacional o del Morro de Arica) y una foto de sus ruinas actuales.","Pregunta: <i>¿Qué es este lugar? ¿Qué partes de Chile reconocen? ¿Qué creen que le pasó?</i> Anota las respuestas en la pizarra.","Cuenta la historia en dos minutos: un parque en Lo Prado que entre 1983 y 2000 mostraba Chile en miniatura; cerró por problemas económicos y hoy está abandonado."]],"des":[60,["<b>¿Qué mostraba y qué no? (20 min).</b> En parejas, los estudiantes completan una tabla de dos columnas en su cuaderno: <i>Lo que el parque mostraba</i> (monumentos, paisajes, estadios) y <i>Lo que no aparece</i>. Guía con preguntas: ¿aparecen personas trabajando? ¿pueblos originarios? ¿mujeres? ¿todas las regiones? <span class=\"di\">Un museo siempre elige. Hoy vamos a pensar qué eligió este parque y qué elegiremos nosotros.</span>","<b>Puesta en común (10 min).</b> Tres o cuatro parejas comparten. Registra en la pizarra las ausencias que se repiten; quedarán escritas para la clase 5.","<b>El desafío (10 min).</b> Presenta la pregunta guía y el producto final: <i>¿Cómo podemos mostrarle a nuestra comunidad el Chile de hoy y cómo llegó a ser así, en un museo hecho por nosotros?</i> Muestra el calendario de cuatro semanas y la fecha de inauguración.","<b>Sorteo de zonas (5 min).</b> Cada equipo saca una tarjeta con su zona y su momento histórico (tabla de equipos de 6.° en el planificador).","<b>Contrato de equipo (15 min).</b> Cada equipo completa la Guía 2: nombre del equipo, roles, acuerdos de convivencia y qué harán si alguien no cumple. Todos firman."]],"cie":[15,["Cada equipo escribe en un papel adhesivo una pregunta que quiera responder sobre su zona y la pega en el mural del proyecto.","Ticket de salida individual: completar la frase <i>«Un museo no muestra todo porque…»</i>."]],"rec":["Proyector y fotos del Mundo Mágico original y de sus ruinas (se encuentran en archivos de prensa digitales; ver Fuentes)","Tarjetas de sorteo con zona y momento histórico (una por equipo)","Mapa político de Chile","Guía 2: Contrato de equipo","Papeles adhesivos y un pliego para el mural del proyecto"],"ev":"<p>Formativa. Revisa los tickets de salida: busca que el estudiante reconozca que un museo selecciona. No lleva nota.</p>","nota":"<p>Si el curso ya tiene equipos que funcionan bien, puedes mantenerlos. Procura que cada equipo tenga al menos un estudiante con facilidad para la escritura y otro para el trabajo manual.</p>","prep":["Imprimir las tarjetas de sorteo de 6.° y la Guía 2.","Definir la fecha y el lugar de la inauguración con la coordinación del proyecto."]},{"r":"his","f":1,"min":90,"t":"Investigamos nuestra zona y nuestro momento","oa":"Historia OA 11 · OA del momento del equipo (2, 4, 5, 6, 13 o 14) · OAH e, f","obj":"Obtener información sobre la zona y el momento histórico desde al menos tres fuentes, registrándola en la ficha de investigación.","ini":[15,["Modela cómo trabaja una historiadora: proyecta una fuente (por ejemplo, una foto antigua de una oficina salitrera) y piensa en voz alta: <i>¿quién la hizo?, ¿cuándo?, ¿para qué?, ¿qué muestra y qué no?</i>","Explica la diferencia entre fuente primaria (de la época: fotos, cartas, diarios) y secundaria (escrita después: textos escolares, enciclopedias).","Presenta la Guía 1 y muestra que hoy se completan las partes A (la zona) y B (el momento)."]],"des":[60,["<b>Reparto (5 min).</b> Cada equipo recibe su dossier de fuentes (preparado según la sección «Cómo se realiza la investigación»). El rol investigador lleva el registro de fuentes.","<b>Parte A: la zona (25 min).</b> Con atlas, texto escolar y dossier, el equipo completa: regiones y capitales, relieve, clima, ríos o lagos importantes, ambiente natural, principales actividades económicas y un rasgo de su población.","<b>Parte B: el momento (25 min).</b> El equipo responde: ¿qué pasó?, ¿cuándo?, ¿quiénes participaron?, ¿qué consecuencias tuvo? Cada dato se anota con su fuente. Al menos una fuente debe mostrar la mirada de quienes no suelen aparecer (trabajadores, mujeres, pueblos originarios, habitantes de la zona).","<b>Monitoreo.</b> Recorre los equipos con la lista de cotejo de la Guía 1. Pregunta: <i>¿De dónde sacaron eso? ¿Lo dicen dos fuentes o solo una?</i>"]],"cie":[15,["Cada equipo comparte en 30 segundos el dato que más le sorprendió.","Recuerda que la ficha se completa en la clase 1 de Lenguaje y que el viernes se entrega (entregable de la semana 1)."]],"rec":["Guía 1: Ficha de investigación (una por equipo)","Dossier de fuentes por equipo","Texto del estudiante de Historia 6.º básico","Atlas escolar","Computadores o tablets (opcional)"],"ev":"<p>Lista de cotejo de la Guía 1 (al final de la guía). Es formativa: la ficha debe estar aprobada para pasar a la semana 2.</p>","nota":"<p>Si no hay computadores, el dossier impreso basta. Si los hay, limita la búsqueda a los sitios recomendados para evitar que copien textos que no entienden.</p>","prep":["Armar un dossier por equipo con 3 a 5 fuentes breves (ver «Cómo se realiza la investigación»).","Imprimir la Guía 1."]},{"r":"his","f":2,"min":90,"t":"¿Por qué pasó ahí? El territorio y la historia","oa":"Historia OA 11 · OA 12 · OA 10 (equipo 7) · OAH a (líneas de tiempo) · OAH l (múltiples causas)","obj":"Explicar cómo las características geográficas de la zona influyeron en el momento histórico y decidir qué escena mostrará el diorama.","ini":[15,["Pregunta disparadora: <i>¿Por qué las oficinas salitreras estaban en el norte y no en el sur?</i> Deja que el curso proponga razones.","Concluye con ellos que el territorio no decide la historia, pero sí la condiciona: hay salitre en el desierto porque casi no llueve."]],"des":[60,["<b>Territorio → hecho (20 min).</b> En la Guía 1, parte C, cada equipo elige tres rasgos de su zona (de la parte A) y escribe cómo cada uno influyó en su momento histórico. Ejemplo modelado en la pizarra con un tema que ningún equipo tenga, como el Morro de Arica en la Guerra del Pacífico: «Es un cerro alto junto al puerto, por eso quien lo controlaba controlaba la bahía».","<b>Línea de tiempo (15 min).</b> El equipo ordena tres a cinco hitos de su momento en una línea de tiempo simple y marca cuál será la escena del diorama.","<b>Elegir la escena (25 min).</b> El equipo decide el instante exacto que mostrará (por ejemplo, no «la Independencia», sino «el cabildo abierto del 18 de septiembre de 1810») y anota quiénes aparecen, qué hacen y qué se ve del territorio. Esta decisión pasa a Artes para el boceto."]],"cie":[15,["Cada equipo explica en un minuto su relación territorio–hecho. Otro equipo le hace una pregunta.","Revisa y firma la parte C de cada Guía 1 (entregable de la semana 2, junto con el plano de Matemática)."]],"rec":["Guía 1, parte C","Atlas y mapas físicos de Chile","Pizarra para el ejemplo modelado"],"ev":"<p>Rúbrica del proyecto, criterio «Relación zona–historia» (formativa en esta clase, sumativa al final).</p>","nota":"<p>El equipo 7 (Chile insular y antártico) trabaja además el carácter tricontinental (OA 10): su escena puede mostrar Rapa Nui en 1888 y un recuadro con la ubicación de Chile en tres continentes.</p>"},{"r":"his","f":3,"min":90,"t":"Curaduría: ¿quiénes aparecen en nuestro diorama?","oa":"Historia OA del momento del equipo · OAH g (contrastar dos fuentes) · OAH j (comparar puntos de vista) · OAA D","obj":"Contrastar dos puntos de vista sobre el momento histórico y decidir cómo representarlos en el diorama.","ini":[15,["Lee en voz alta dos relatos breves sobre un mismo hecho, escritos desde lugares distintos (por ejemplo, un dueño de oficina salitrera y un trabajador pampino describiendo la misma faena).","Pregunta: <i>¿Cuentan lo mismo? ¿Por qué cambia el relato según quién lo cuenta?</i>"]],"des":[60,["<b>Dos miradas (25 min).</b> Con la Guía 1, parte D, cada equipo compara dos fuentes de su dossier: quién escribe, qué destaca cada una, en qué coinciden y en qué difieren.","<b>Revisión del diorama (20 min).</b> Con el diorama en construcción a la vista (o el boceto), el equipo responde: <i>¿Qué voz falta en nuestra escena?</i> y agrega al menos un elemento que la represente: un personaje, un cartel, una vivienda, un objeto.","<b>Revisión de contenido (15 min).</b> Pasa por cada equipo con la lista de verificación histórica: fechas correctas, personajes correctos, nada anacrónico (por ejemplo, autos en 1810), relación con el territorio clara. <span class=\"di\">Un buen curador no solo pregunta si está lindo, sino si es verdad y si está completo.</span>"]],"cie":[15,["Cada equipo comparte qué voz agregó y por qué.","Recuerda que la cédula final (Lenguaje) debe incluir una línea con la otra mirada."]],"rec":["Guía 1, parte D","Dossier de fuentes","Dioramas en construcción o bocetos","Lista de verificación histórica (en esta planificación)"],"ev":"<p>Formativa con la lista de verificación:</p>\n    <ul class=\"lista-chequeo\">\n      <li><label><input type=\"checkbox\"><span>Las fechas y los personajes son correctos.</span></label></li>\n      <li><label><input type=\"checkbox\"><span>No hay elementos de otra época.</span></label></li>\n      <li><label><input type=\"checkbox\"><span>La escena muestra algo del territorio que explica el hecho.</span></label></li>\n      <li><label><input type=\"checkbox\"><span>Aparece al menos una mirada además de la oficial.</span></label></li>\n    </ul>","nota":"<p>Los equipos 5, 6 y 7 trabajan conflictos con pueblos originarios (mapuche, kawésqar, aónikenk, selk'nam, rapanui). Usa fuentes de ambas partes. Si hay estudiantes de esos pueblos en el curso, invita a sus familias como fuentes y respeta si no quieren participar; nunca los conviertas en objeto de estudio.</p>","prep":["Preparar dos relatos breves sobre un mismo hecho para el inicio."]},{"r":"his","f":4,"min":90,"t":"Inauguración del Mundo Mágico Miniatura Escolar","oa":"Historia OA 20 (cuidado del patrimonio) · OA 21 · OAH n · OAH j","obj":"Presentar el museo a la comunidad y reflexionar críticamente sobre la representación del país que construyó el curso.","ini":[15,["Revisión final del montaje: cada diorama junto a su región en la Gran Maqueta, cédulas visibles, timbres y pasaportes listos.","Repasa los turnos de guía (ver «La jornada del museo») y las normas: los visitantes miran sin tocar, los guías cuidan su diorama."]],"des":[60,["<b>Museo abierto.</b> Llegan los cursos visitantes y las familias según el horario de la jornada. Cada estudiante cumple al menos un turno como guía y otro como visitante con su propio pasaporte.","<b>Tu rol durante la visita:</b> recorrer, observar y anotar en una lista simple qué guía explica sin leer, quién responde preguntas y quién relaciona territorio e historia (insumo para la rúbrica)."]],"cie":[15,["Con el curso sentado frente a la Gran Maqueta, retoma la pizarra de la clase 1 con lo que el Mundo Mágico original dejaba fuera.","Pregunta: <i>¿Qué Chile mostramos nosotros? ¿Qué dejamos fuera? ¿Qué agregarían si el museo durara un año más?</i>","Cada estudiante completa la Guía 10 (autoevaluación y reflexión). Puede terminarla en la casa."]],"rec":["Gran Maqueta y dioramas montados","Pasaportes (Guía 8) y timbres","Guía 10: Autoevaluación y reflexión","Lista de observación del docente"],"ev":"<p>Sumativa con la rúbrica del proyecto, criterios de Historia: contenido histórico, relación zona–historia y trabajo en equipo. La reflexión escrita se considera en el criterio de contenido.</p>","nota":"<p>Toma fotos del museo solo de estudiantes con autorización de uso de imagen. Las fotos y una breve nota de los visitantes son la evidencia del proyecto para el colegio.</p>"},{"r":"len","f":1,"min":90,"t":"¿Puedo confiar en esta fuente?","oa":"Lenguaje OA 11 · OA 7 · OA 8","obj":"Evaluar la confiabilidad de distintas fuentes y registrar con palabras propias las ideas principales que aportan a la investigación del equipo.","ini":[15,["Proyecta dos fuentes sobre un mismo tema: un comentario anónimo en una red social y la página de una institución (un museo o la Biblioteca Nacional).","Pregunta: <i>¿A cuál le creerían más? ¿Por qué?</i> Construye con el curso tres preguntas para evaluar cualquier fuente: <b>¿Quién lo escribe? ¿Para qué? ¿Cuándo?</b>"]],"des":[60,["<b>Evaluar el dossier (15 min).</b> Cada equipo aplica las tres preguntas a cada fuente de su dossier y marca su confiabilidad en la tabla de fuentes de la Guía 1.","<b>Sintetizar sin copiar (20 min).</b> Modela con un párrafo: lees, subrayas la idea principal, tapas el texto y la escribes en una oración propia. <span class=\"di\">Si no lo puedo decir con mis palabras, todavía no lo entendí.</span> Cada estudiante practica con un párrafo de su dossier.","<b>Completar la ficha (25 min).</b> Los equipos terminan las partes A y B de la Guía 1 con oraciones propias y la fuente de cada dato. Revisa con la lista de cotejo."]],"cie":[15,["Cada equipo lee en voz alta su mejor oración propia.","Firma las fichas que cumplen la lista de cotejo. Las que no, se completan como tarea antes del lunes."]],"rec":["Guía 1: Ficha de investigación (tabla de fuentes)","Dossier de fuentes por equipo","Proyector con dos fuentes de ejemplo","Destacadores"],"ev":"<p>Lista de cotejo de la Guía 1. Es el <b>entregable de la semana 1</b>: sin ficha aprobada el equipo no pasa al diseño.</p>","nota":"<p>Para estudiantes con dificultades lectoras, prepara en el dossier una versión de lectura fácil de cada fuente (oraciones cortas, vocabulario explicado al margen).</p>"},{"r":"len","f":2,"min":90,"t":"¿Qué es una cédula de museo?","oa":"Lenguaje OA 17 · OA 15 · OA 27","obj":"Planificar la cédula del diorama estableciendo su propósito, su destinatario y su estructura, y escribir un primer borrador.","ini":[15,["Muestra dos o tres cédulas reales (fotos tomadas en museos o la cédula modelo de la Guía 6).","Pregunta: <i>¿Qué tienen en común? ¿Para quién están escritas? ¿Cuánto tiempo se queda una persona leyéndolas?</i> Concluyan: son breves, claras y responden lo que el visitante se pregunta al mirar."]],"des":[60,["<b>Propósito y destinatario (10 min).</b> En la Guía 6, el equipo define: <i>¿Para quién escribimos?</i> (estudiantes de 2.º básico y familias) y <i>¿qué queremos que entiendan en un minuto?</i>","<b>Estructura (10 min).</b> Explica las cinco partes con la cédula modelo: título atractivo, qué se ve, qué pasó y cuándo, por qué aquí, otra mirada. Más la fuente. Extensión: 80 a 120 palabras.","<b>Escribir por partes (25 min).</b> Cada integrante escribe una parte en una tira de papel, usando la Guía 1 como base. Luego el equipo las ordena y las une en un borrador.","<b>Acuerdos (15 min).</b> El equipo lee el borrador completo en voz alta y acuerda cambios: ¿se entiende?, ¿sobra algo?, ¿falta el porqué? El rol curador cuida que se respete lo que el equipo decidió."]],"cie":[15,["Intercambio entre equipos: cada uno lee el borrador de otro y deja «dos estrellas y un deseo» (dos cosas que funcionan y una que mejorar)."]],"rec":["Guía 6: Cédula de museo (con cédula modelo)","Guía 1 completa","Tiras de papel","Fotos de cédulas reales (opcional)"],"ev":"<p>Formativa con «dos estrellas y un deseo». El borrador se revisa de nuevo en Historia (clase 4) para el contenido.</p>"},{"r":"len","f":3,"min":90,"t":"Revisar la cédula y escribir el guion","oa":"Lenguaje OA 18 · OA 15 · OA 29","obj":"Revisar y editar la cédula para que comunique con claridad, y planificar el guion de una visita guiada de dos minutos.","ini":[15,["Proyecta una cédula con errores preparados (repeticiones, una oración de cinco líneas, una falta de ortografía, sin fuente). Corrígela con el curso en voz alta."]],"des":[60,["<b>Revisión con pauta (20 min).</b> Cada equipo aplica la pauta de revisión de la Guía 6 a su borrador: una idea por párrafo, oraciones de menos de dos líneas, palabras precisas, ortografía, fuente, entre 80 y 120 palabras.","<b>Versión final (15 min).</b> La pasan en limpio con letra clara o en el procesador de textos (si Tecnología lo coordina). El tamaño de letra debe leerse a un metro de distancia.","<b>Guion de la visita (25 min).</b> Con la Guía 7, el equipo planifica dos minutos de visita: <i>introducción</i> (saludo y zona), <i>desarrollo</i> (qué se ve, qué pasó, por qué ahí), <i>cierre</i> (una pregunta al público y el timbre del pasaporte). Escriben palabras clave, no un texto para leer. <span class=\"di\">El guion es un mapa, no un libreto: si lo leen, el público deja de mirar el diorama.</span>"]],"cie":[15,["En parejas, cada estudiante dice la visita a su compañero usando solo las palabras clave. El compañero cronometra."]],"rec":["Guía 6 (pauta de revisión)","Guía 7: Guion de la visita guiada","Cédula con errores para proyectar","Cartulina o computador e impresora","Cronómetro"],"ev":"<p>La <b>cédula final</b> se califica con la rúbrica del proyecto, criterio «Cédula». Es parte del entregable de la semana 3.</p>"},{"r":"len","f":4,"min":90,"t":"Ensayo general de la visita guiada","oa":"Lenguaje OA 29 · OA 27","obj":"Exponer la visita guiada de forma clara y sin leer, y retroalimentar a otro equipo con una pauta.","ini":[15,["Modela una visita guiada de dos minutos sobre un objeto de la sala (o un diorama). Hazlo una vez leyendo un papel y otra mirando al público.","Pregunta: <i>¿Cuál prefirieron? ¿Qué hice distinto?</i> Anota en la pizarra lo que observaron: mirar al público, señalar, voz audible, pausas, una pregunta final."]],"des":[60,["<b>Rondas de ensayo (45 min).</b> Los equipos se ordenan en pares. El equipo A guía al equipo B frente a su diorama (2 min de visita + 1 min de preguntas). El equipo B completa la pauta de coevaluación de la Guía 9. Luego se invierten. Haz tres rondas cambiando de pareja, para que cada guía practique al menos una vez.","<b>Ajustes (15 min).</b> Cada equipo lee las pautas que recibió y anota en su guion dos mejoras concretas."]],"cie":[15,["Ronda de bienvenida: cada estudiante dice en voz alta, de pie, la frase con la que recibirá a los visitantes."]],"rec":["Guía 7 (guion)","Guía 9: Pauta de coevaluación","Dioramas terminados","Cronómetro"],"ev":"<p>Formativa con la coevaluación. La <b>visita guiada</b> se califica durante la inauguración con la rúbrica del proyecto, criterio «Visita guiada».</p>","nota":"<p>Estudiantes con ansiedad al hablar en público pueden guiar en pareja, partir con un público pequeño (un curso menor) o usar una tarjeta con dibujos en vez de palabras.</p>"},{"r":"mat","f":1,"min":90,"t":"¿Cómo cabe Chile en la sala?","oa":"Matemática OA 3 · OA 2 · OAH k","obj":"Comprender la escala como una razón y usarla para convertir distancias reales en distancias de la maqueta.","ini":[15,["Plantea el problema: <i>Chile continental mide unos 4.200 km de Arica al Cabo de Hornos. Queremos construirlo en el pasillo del colegio. ¿Cómo lo hacemos?</i>","Recoge ideas sin corregir. Lleva la conversación a que hay que «achicar todo lo mismo»."]],"des":[60,["<b>Concreto (15 min).</b> Cada pareja recibe una tira de papel de 42 cm. Si toda la tira es Chile, ¿cuántos km representa cada centímetro? (100 km). ¿Y si la tira midiera 4,2 m? (10 km por centímetro).","<b>Pictórico (10 min).</b> Dibuja en la pizarra una tabla de razón: 1 cm ↔ 10 km; 2 cm ↔ 20 km; 10 cm ↔ 100 km; 100 cm ↔ 1.000 km. Pregunta qué patrón ven.","<b>Simbólico (10 min).</b> Explica la notación 1:1.000.000: 1 cm en la maqueta equivale a 1.000.000 cm reales, es decir, 10 km. Muestra el paso: 1.000.000 cm = 10.000 m = 10 km.","<b>Práctica (25 min).</b> Guía 3B, parte A: convertir distancias (por ejemplo, el ancho máximo de Chile, unos 445 km, son 44,5 cm; el mínimo, unos 90 km, son 9 cm). Al final, comparar con otra escala: 1:2.000.000. ¿Cuánto mediría Chile? ¿Cabría mejor? ¿Qué se pierde?"]],"cie":[15,["Ticket de salida: <i>Dos ciudades están a 350 km. ¿A cuántos centímetros quedan en la maqueta a escala 1:1.000.000? Explica cómo lo calculaste.</i> (35 cm)"]],"rec":["Guía 3B: Escala y plano, parte A","Tiras de papel de 42 cm","Huinchas o reglas","Mapa de Chile con escala gráfica"],"ev":"<p>Formativa con el ticket de salida. Quien no llegue a 35 cm repasa la tabla de razón al inicio de la clase 2.</p>","alt":"his"},{"r":"mat","f":2,"min":90,"t":"Distancias en la Gran Maqueta","oa":"Matemática OA 3 · OA 2 · OAH g","obj":"Usar la razón 1 : 1.000.000 (1 cm = 10 km) para calcular distancias entre capitales regionales y comprobarlas sobre la Gran Maqueta que construye 5.° básico, y dibujar el plano del diorama.","ini":[10,["Revisa el ticket de salida en la pizarra. Recuerda el dato clave: un grado de latitud mide unos 111 km de norte a sur."]],"des":[65,["<b>De la latitud a los kilómetros (25 min).</b> Con la tabla de capitales de la Guía 3B, cada equipo calcula la distancia norte–sur entre Santiago y dos capitales: diferencia de latitud × 111 = km. Luego, ÷ 10 = cm en la maqueta.","<b>Comprobar en la maqueta (15 min).</b> Con huincha, miden esas distancias sobre la Gran Maqueta de 5.° (o sobre su plano, si aún no está armada) y comparan. <span class=\"di\">Si la medida y el cálculo no coinciden, ¿el error está en la maqueta o en el cálculo?</span>","<b>El plano del diorama (25 min).</b> Cada equipo mide su caja y dibuja en la cuadrícula de la Guía 3B la vista desde arriba, ubicando los elementos del boceto de Artes."]],"cie":[15,["Revisa y firma cada plano. Es el <b>entregable de la semana 2</b>, junto con el boceto de Artes."]],"rec":["Guía 3B, partes B y C","Calculadoras","Huinchas","Cajas de los dioramas","Solucionario (en esta planificación)"],"ev":"<p>Rúbrica común, criterio «Escala y medidas» (formativa).</p><h4>Solucionario: distancias desde Santiago</h4><div class=\"tabla\"><table><thead><tr><th>Desde Santiago hasta</th><th>Latitud</th><th>Diferencia</th><th>Distancia aprox. norte–sur</th><th>En la maqueta</th></tr></thead><tbody><tr><td>Arica</td><td>18,5° S</td><td>14,9°</td><td>1.654 km</td><td>165 cm</td></tr><tr><td>Iquique</td><td>20,2° S</td><td>13,2°</td><td>1.465 km</td><td>147 cm</td></tr><tr><td>Antofagasta</td><td>23,6° S</td><td>9,8°</td><td>1.088 km</td><td>109 cm</td></tr><tr><td>Copiapó</td><td>27,4° S</td><td>6,0°</td><td>666 km</td><td>67 cm</td></tr><tr><td>La Serena</td><td>29,9° S</td><td>3,5°</td><td>388 km</td><td>39 cm</td></tr><tr><td>Valparaíso</td><td>33,0° S</td><td>0,4°</td><td>44 km</td><td>4 cm</td></tr><tr><td>Rancagua</td><td>34,2° S</td><td>0,8°</td><td>89 km</td><td>9 cm</td></tr><tr><td>Talca</td><td>35,4° S</td><td>2,0°</td><td>222 km</td><td>22 cm</td></tr><tr><td>Chillán</td><td>36,6° S</td><td>3,2°</td><td>355 km</td><td>36 cm</td></tr><tr><td>Concepción</td><td>36,8° S</td><td>3,4°</td><td>377 km</td><td>38 cm</td></tr><tr><td>Temuco</td><td>38,7° S</td><td>5,3°</td><td>588 km</td><td>59 cm</td></tr><tr><td>Valdivia</td><td>39,8° S</td><td>6,4°</td><td>710 km</td><td>71 cm</td></tr><tr><td>Puerto Montt</td><td>41,5° S</td><td>8,1°</td><td>899 km</td><td>90 cm</td></tr><tr><td>Coyhaique</td><td>45,6° S</td><td>12,2°</td><td>1.354 km</td><td>135 cm</td></tr><tr><td>Punta Arenas</td><td>53,2° S</td><td>19,8°</td><td>2.198 km</td><td>220 cm</td></tr></tbody></table></div><p>Latitudes redondeadas. Acepta diferencias de ±2 cm. Si 5.° no participa en el museo, 6.° construye la Gran Maqueta con las sesiones de 5.° y la Guía 3A.</p>","nota":"<p>Para estudiantes que lo necesiten, entrega la tabla con la columna de diferencia de latitud ya calculada, de modo que solo multipliquen y dividan.</p>","alt":"his"},{"r":"mat","f":3,"min":90,"t":"Control de calidad: superficie y medidas","oa":"Matemática OA 13 · OA 18 · OA 2 · OAH g","obj":"Calcular la superficie de la caja del diorama a partir de su red para forrarla, y comprobar las medidas de la capa de regiones.","ini":[15,["Muestra una caja de zapatos sin tapa. Pregunta: <i>¿Cuánto papel necesitamos para forrarla por fuera? ¿Cómo lo sabemos sin desperdiciar?</i>","Abre una caja (o dibuja su red) para mostrar que la superficie es la suma de las caras."]],"des":[60,["<b>La red de nuestra caja (25 min).</b> En la Guía 3B, parte D, cada equipo dibuja la red de su caja sin tapa (5 caras), anota las medidas y calcula el área de cada cara y el total en cm².","<b>Cortar con el cálculo (10 min).</b> Cortan el papel de forrar según su cálculo, con 1 cm extra por lado para doblar. Comprueban si alcanzó.","<b>Control de la capa de regiones (25 min).</b> Miden sobre la Gran Maqueta la distancia entre dos banderines de capitales y la comparan con su cálculo de la clase 2. Si la diferencia supera 5 cm, explican la causa y corrigen la ubicación del banderín."]],"cie":[15,["Cada equipo comparte qué error encontró y cómo lo corrigió. Valora los errores explicados tanto como los aciertos."]],"rec":["Guía 3B, parte D","Cajas de los dioramas y una caja de muestra para abrir","Papel para forrar","Reglas, huinchas y tijeras","Calculadoras"],"ev":"<p>Sumativa con la rúbrica del proyecto, criterio «Escala y medidas», usando las partes B, C y D de la Guía 3.</p>","alt":"his"},{"r":"cie","f":1,"min":90,"t":"Los recursos y la energía de nuestra zona","oa":"Ciencias OA 16 · OA 11","obj":"Describir los recursos que la litósfera y la hidrósfera entregan a la zona, y clasificar sus fuentes de energía en renovables y no renovables.","ini":[15,["Pregunta: <i>¿De dónde viene la luz de esta sala? ¿Y el agua de la llave? ¿Y el cobre del cable?</i> Ubica cada respuesta en un dibujo rápido de las capas de la Tierra: atmósfera, litósfera, hidrósfera."]],"des":[60,["<b>Las tres capas (15 min).</b> Explica qué recursos entrega cada capa y cómo la actividad humana las afecta. Usa ejemplos de distintas zonas del país.","<b>Investigación de la zona (30 min).</b> Con el dossier y el texto escolar, cada equipo completa la Guía 4B, parte A: dos recursos de la litósfera (minerales, suelos agrícolas), uno de la hidrósfera (ríos, lagos, mar) y las fuentes de energía que se producen en su zona, clasificadas en renovables o no renovables.","<b>¿Qué irá en la maqueta? (15 min).</b> El equipo elige un recurso y una fuente de energía para representar en su región de la Gran Maqueta con un símbolo (por ejemplo, paneles solares, una represa, una mina, un molino eólico) y lo dibuja en la guía."]],"cie":[15,["Cada equipo propone una medida concreta para proteger una de las capas en su zona (OA 16) y la escribe en una tarjeta para el mural del proyecto."]],"rec":["Guía 4B, parte A","Dossier de fuentes de la zona","Texto del estudiante de Ciencias Naturales 6.º básico"],"ev":"<p>Formativa con la parte A de la Guía 4. Revisa que la clasificación renovable / no renovable esté bien fundamentada.</p>","nota":"<p>Para que los equipos no repitan lo mismo, conviene que el dossier de cada zona incluya un dato sobre su matriz energética (por ejemplo, energía solar en el norte, hidroeléctrica en el sur).</p>","alt":"his"},{"r":"cie","f":2,"min":90,"t":"Experimento: ¿qué papel maché seca antes?","oa":"Ciencias OA 13 · Habilidades a, b, c, d, e","obj":"Investigar experimentalmente cómo la cantidad de agua de la mezcla influye en el tiempo de secado del papel maché, explicándolo como evaporación.","ini":[15,["Pregunta: <i>Cuando el papel maché se seca, ¿a dónde se va el agua?</i> Lleva la conversación a la evaporación: el agua pasa de líquido a gas.","Plantea la pregunta de investigación: <i>¿Cómo cambia el tiempo de secado si la mezcla tiene más o menos agua?</i> Cada estudiante escribe su predicción en la Guía 4B, parte B."]],"des":[60,["<b>Las variables (10 min).</b> Identifica con el curso: variable que cambiamos (proporción de agua en la mezcla), variable que medimos (tiempo de secado) y variables que mantenemos iguales (tamaño de la muestra, cantidad de capas, lugar).","<b>Preparar las muestras (30 min).</b> Cada equipo prepara tres muestras iguales: un cuadrado de cartón de 10 × 10 cm con tres capas de tiras de diario. Cambia solo la mezcla: <ul><li>Muestra A: 1 parte de cola fría por 1 de agua.","Muestra B: 1 parte de cola fría por 2 de agua.","Muestra C: 1 parte de cola fría por 3 de agua.","<b>Primer registro (20 min).</b> A los 30 minutos, observan y registran en la tabla: ¿está húmeda, mojada o seca al tacto? Si hay balanza, pesan cada muestra al inicio y ahora: la masa que se perdió es agua evaporada."]],"cie":[15,["Ordena con el curso cómo se cuidarán las muestras hasta el día siguiente.","<b>Al día siguiente (5 min):</b> segundo registro. Cada equipo compara con su predicción, escribe una conclusión y elige la mezcla que usará en su diorama."]],"rec":["Guía 4B, parte B","Cartón, diario, cola fría, agua y vasos medidores","Etiquetas","Balanza de cocina (opcional)","Paños para limpiar"],"ev":"<p>Informe del experimento (Guía 4B, parte B): predicción, tabla de registro, conclusión y una mejora al procedimiento. Se califica con la pauta de la guía.</p>","nota":"<p>Este experimento conecta con Matemática: la proporción cola–agua es una razón. Si lo coordinas, en Matemática pueden expresar cada mezcla como 1:1, 1:2 y 1:3.</p>","prep":["Reunir diario, cola fría, cartón y vasos medidores (lista de materiales del proyecto).","Definir un lugar de la sala donde las muestras puedan quedar hasta el día siguiente."],"alt":"his"},{"r":"cie","f":3,"min":90,"t":"Suelo y erosión en nuestra maqueta","oa":"Ciencias OA 17 · OA 18 · Habilidades c, e, f","obj":"Describir propiedades del suelo y explicar el principal agente de erosión de la zona, representándolo correctamente en el diorama o en el tramo.","ini":[15,["Demostración: dos bandejas inclinadas con tierra; una desnuda y otra cubierta de pasto o musgo. Riega ambas con la misma cantidad de agua.","Pregunta: <i>¿Qué pasó en cada una? ¿Por qué?</i> Introduce el concepto de erosión y sus agentes: agua, viento y actividad humana."]],"des":[60,["<b>Observar suelos (25 min).</b> En estaciones, cada equipo observa tres muestras (arena, tierra de hoja, arcilla): color, textura al tacto y cuánta agua retienen (vaso con agujeros sobre otro vaso, misma cantidad de agua). Registran en la Guía 4B, parte C.","<b>La erosión de nuestra zona (20 min).</b> Con el dossier, el equipo identifica el principal agente de erosión de su zona (por ejemplo, el viento en el desierto, el agua en las zonas lluviosas, la actividad minera o forestal) y su efecto visible en el paisaje.","<b>Llevarlo a la maqueta (15 min).</b> Deciden cómo representarlo: dunas, quebradas, cerros sin vegetación, sedimentos en un río. Lo agregan al diorama o al tramo."]],"cie":[15,["Cada equipo explica en 30 segundos su agente de erosión y lo agrega como una oración a su cédula: «En esta zona, el ___ da forma al paisaje porque…»."]],"rec":["Guía 4B, parte C","Dos bandejas, tierra, pasto o musgo y una regadera","Muestras de arena, tierra de hoja y arcilla","Vasos plásticos (con y sin agujeros)","Agua"],"ev":"<p>Sumativa con la Guía 4B completa (partes A, B y C) y la representación de la erosión en la maqueta.</p>","alt":"his"},{"r":"art","f":1,"min":90,"t":"Mirar dioramas: ¿cómo cuenta una historia una escena?","oa":"Artes OA 4 · OAA D","obj":"Analizar dioramas y maquetas identificando cómo usan el volumen, el color y la composición para contar una historia.","ini":[15,["Proyecta imágenes de dioramas de museos (por ejemplo, las escenas de animales del Museo Nacional de Historia Natural) y de las miniaturas del Mundo Mágico original.","Pregunta: <i>¿Qué historia cuenta esta escena? ¿Cómo lo sabes si no tiene texto?</i>"]],"des":[60,["<b>Análisis guiado (25 min).</b> En equipos, analizan dos imágenes con la Guía 5, parte A: primer plano y fondo, tamaño de las figuras (¿qué parece cerca y qué lejos?), punto de vista, colores dominantes, qué está lleno y qué está vacío, qué detalle llama la atención primero.","<b>Puesta en común (10 min).</b> Construye con el curso una lista de «trucos» de un buen diorama: fondo pintado que continúa el paisaje, figuras más chicas al fondo, un foco claro, pocos colores bien elegidos.","<b>Prueba de técnicas (25 min).</b> Estaciones rápidas: un árbol con alambre o limpiapipas y papel, una figura humana de plasticina de 5 cm, una roca de papel maché, agua con papel celofán. Cada estudiante prueba al menos dos."]],"cie":[15,["Cada equipo anota qué técnicas usará y por qué, pensando en su zona y su momento."]],"rec":["Guía 5, parte A","Imágenes de dioramas y maquetas para proyectar","Plasticina, alambre o limpiapipas, papel, celofán, diario y cola fría"],"ev":"<p>Formativa con la Guía 5, parte A. Cuenta como parte de la observación de obras que pide el OA 4.</p>"},{"r":"art","f":2,"min":90,"t":"El boceto del diorama","oa":"Artes OA 1 · OA 2","obj":"Diseñar el boceto del diorama definiendo la escena, los planos, el volumen y la paleta de color según la zona y el momento histórico.","ini":[15,["Cada equipo recuerda en voz alta la escena que eligió en Historia (clase 3): qué instante, quiénes aparecen, qué se ve del territorio.","Muestra cómo cambia una misma escena con dos paletas: ocres y amarillos (desierto) frente a verdes y azules (sur lluvioso)."]],"des":[60,["<b>Boceto frontal (20 min).</b> En la Guía 5, parte B, cada estudiante dibuja la escena vista de frente, con fondo, plano medio y primer plano. Luego el equipo elige uno o combina varios.","<b>Vista desde arriba (10 min).</b> Dibujan dónde va cada elemento dentro de la caja, usando las medidas del plano de Matemática.","<b>Paleta y volumen (15 min).</b> Eligen 4 a 6 colores según el ambiente natural de la zona y deciden qué elementos tendrán volumen (modelados) y cuáles serán planos (pintados en el fondo).","<b>Lista de elementos (15 min).</b> Completan la tabla de elementos: qué es, material, técnica y responsable. Se coordina con el plan de construcción de Tecnología."]],"cie":[15,["Galería: los bocetos se pegan en la pared; cada estudiante deja un comentario en un papel adhesivo en el boceto de otro equipo.","Revisa y firma los bocetos (<b>entregable de la semana 2</b>)."]],"rec":["Guía 5, parte B","Lápices de colores y de grafito","Plano del diorama (Guía 3B, parte C)","Papeles adhesivos"],"ev":"<p>Formativa. Revisa que el boceto muestre un foco claro y una paleta coherente con la zona.</p>"},{"r":"art","f":3,"min":90,"t":"Construcción del diorama","oa":"Artes OA 3 · OA 2","obj":"Construir el diorama aplicando técnicas de modelado y técnicas mixtas con materiales reciclados y naturales.","ini":[10,["Normas de seguridad: tijeras y cartonero solo en la mesa de corte y con supervisión; pegamento caliente, si se usa, solo lo manipula el docente.","Organiza cuatro estaciones y explica que cada equipo rota según su lista de elementos."]],"des":[70,["<b>Estaciones (70 min).</b> El rol escenógrafo dirige y reparte tareas: <ul> <li><b>Fondo:</b> pintar el paisaje en el fondo y los lados de la caja (témpera).","<b>Relieve:</b> modelar cerros, quebradas o costas con papel maché, usando la mezcla elegida en Ciencias.","<b>Figuras:</b> personas, animales y construcciones de plasticina, palitos y envases.","<b>Naturaleza:</b> vegetación con ramas, musgo seco o esponja teñida; agua con celofán; nieve con algodón; arena o sémola para el desierto.","Recorre los equipos con el boceto en mano. Pregunta: <i>¿Se ve el foco de la escena? ¿Se distingue lo cercano de lo lejano?</i>"]],"cie":[10,["Limpieza por equipo. Foto de avance del diorama. Cada equipo anota en una línea qué le falta para terminar."]],"rec":["Cajas forradas (Matemática, clase 3)","Témperas, pinceles, papel maché, plasticina","Materiales reciclados y naturales (lista del proyecto)","Mesa de corte con tijeras y cartonero"],"ev":"<p>Rúbrica del proyecto, criterio «Construcción» (formativa en esta clase). El diorama terminado es el <b>entregable de la semana 3</b>.</p>","nota":"<p>El papel maché necesita un día para secar. Si es posible, adelanta el relieve a un recreo o a la clase de Tecnología de la misma semana, y deja las figuras para el final.</p>"},{"r":"art","f":4,"min":90,"t":"Crítica de arte y montaje del museo","oa":"Artes OA 5 · OAA E, G","obj":"Evaluar críticamente los dioramas propios y de sus pares con criterios del lenguaje visual, y montar la exposición.","ini":[15,["Pregunta: <i>¿Cómo se cuelga o se ubica una obra en un museo?</i> Altura de los ojos, luz, espacio para circular, orden del recorrido.","Explica que una crítica de arte respetuosa describe, interpreta y sugiere; nunca dice solo «me gusta» o «está feo»."]],"des":[60,["<b>Detalles finales (20 min).</b> Los equipos terminan lo pendiente y retocan.","<b>Crítica en galería (25 min).</b> Cada estudiante evalúa dos dioramas de otros equipos con la Guía 9, parte B: qué emoción o idea transmite, cómo usa los materiales, qué elemento del lenguaje visual destaca y una sugerencia.","<b>Montaje (15 min).</b> Con la coordinación del proyecto, ubican cada diorama junto a su región en la Gran Maqueta de la Gran Maqueta, a una altura cómoda para niños de cursos menores."]],"cie":[15,["Cada equipo lee las críticas que recibió y elige una mejora para hacer antes de la inauguración, si alcanza."]],"rec":["Guía 9, parte B","Dioramas","Mesas para el montaje","Materiales de retoque"],"ev":"<p>Sumativa con la rúbrica del proyecto, criterio «Construcción» (diorama terminado) y la pauta de crítica (OA 5).</p>"},{"r":"tec","f":1,"min":45,"t":"Diseñar la capa de regiones","oa":"Tecnología OA 1","obj":"Diseñar un sistema para marcar las 16 regiones y sus capitales sobre la Gran Maqueta de 5.° básico sin dañarla.","ini":[5,["Plantea el problema: <i>5.° construye el relieve de Chile; nosotros debemos mostrar sus regiones y capitales encima, sin pegar nada sobre su trabajo y de modo que se pueda sacar.</i>"]],"des":[30,["<b>Propuestas (15 min).</b> Cada equipo dibuja a mano alzada una solución: banderines clavados en plasticina, una lámina transparente con los límites, hitos de cartón que se apoyan.","<b>Criterios (5 min).</b> Que no dañe la maqueta, que se lea a un metro, que sea barato y reciclable.","<b>Votación (10 min).</b> Presentan en un minuto y el curso elige."]],"cie":[10,["Registra el diseño ganador en un afiche y acuerda con el curso de 5.° cómo y cuándo se instalará."]],"rec":["Hojas para bocetos","Afiche","Muestras de banderines, mica transparente o cartón"],"ev":"<p>Formativa. Observa que las propuestas respondan al problema y se puedan dibujar con claridad.</p>","nota":"<p>Este diseño depende de la Gran Maqueta de 5.° básico. Si 5.° no participa, usa las sesiones de Tecnología de 5.° para construirla.</p>","alt":"art"},{"r":"tec","f":2,"min":45,"t":"Planificar la capa de regiones y el diorama","oa":"Tecnología OA 2","obj":"Planificar la construcción de la capa de regiones y del diorama: acciones, responsables, tiempos, materiales, costos e impacto ambiental.","ini":[5,["Muestra una lista desordenada de pasos para hacer un queque y pregunta qué pasa si se hacen en otro orden. Concluye: planificar es decidir el orden, los tiempos y los recursos antes de empezar."]],"des":[30,["<b>Plan de construcción (20 min).</b> Con la Guía 5, parte C, cada equipo completa: acción, responsable, tiempo estimado, materiales y si se compran o se reciclan. Usan el largo del tramo calculado en Matemática y la lista de elementos de Artes.","<b>Costo e impacto (10 min).</b> Calculan cuánto costaría lo que hay que comprar y marcan qué materiales son reciclados. Proponen cómo reducir el gasto y la basura."]],"cie":[10,["Cada equipo comparte su material reciclado más ingenioso. Revisa que el plan esté completo y sea realista para la semana 3."]],"rec":["Guía 5, parte C","Lista de materiales del proyecto","Calculadoras"],"ev":"<p>Formativa con la Guía 5, parte C.</p>","alt":"art"},{"r":"tec","f":3,"min":45,"t":"Construir e instalar la capa de regiones","oa":"Tecnología OA 3 · OA 4","obj":"Construir los banderines o hitos de las regiones y probar que se lean bien y no dañen la Gran Maqueta.","ini":[5,["Recuerda los criterios de prueba: se lee a un metro, se sostiene, se puede sacar sin dañar."]],"des":[30,["<b>Construcción (20 min).</b> Cada equipo fabrica los banderines de las regiones de su zona: nombre de la región, capital y número romano.","<b>Instalación y prueba (10 min).</b> Con el curso de 5.°, instalan los banderines y comprueban que se lean y que la maqueta quede intacta."]],"cie":[10,["Evaluación entre equipos con los criterios y una corrección por equipo."]],"rec":["Cartulina, palitos de brocheta sin punta, plasticina","Plumones","La Gran Maqueta"],"ev":"<p>Sumativa con la capa de regiones terminada y probada (OA 3 y 4).</p>","alt":"art"},{"r":"tec","f":4,"min":45,"t":"Difundir el museo de todo el colegio","oa":"Tecnología OA 6 · OA 7","obj":"Crear con un procesador de textos la invitación del museo de todo el colegio y planificar su difusión segura. 6.° básico es el equipo de difusión.","ini":[5,["Muestra dos invitaciones: una con todos los datos y otra a la que le falta la hora. Pregunta qué problema causa la segunda."]],"des":[30,["<b>Invitación (15 min).</b> En parejas, en el procesador de textos: título del museo, fecha, hora, lugar, a quién se invita y una imagen o dibujo propio. El curso elige la mejor para imprimir.","<b>Entrada y pasaporte (10 min).</b> Diseñan la entrada gratuita (con el nombre del museo y un espacio para el nombre del visitante) y revisan la tapa del pasaporte (Guía 8).","<b>Difusión segura (5 min).</b> Conversan: ¿por qué no publicar fotos de compañeros sin permiso? ¿qué datos no se publican? Acuerdan difundir solo por los canales oficiales del colegio."]],"cie":[10,["Guardan los archivos en una carpeta del curso y el docente los envía a impresión y a la comunicación del colegio."]],"rec":["Computadores con procesador de textos","Impresora","Guía 8 (tapa del pasaporte)"],"ev":"<p>Sumativa con la invitación terminada: datos completos, formato legible y archivo guardado correctamente.</p>","nota":"<p>Si no hay computadores para todos, la invitación se puede hacer a mano y digitalizarla con una foto. Lo importante del OA 7 es la conversación sobre privacidad y canales seguros.</p>","alt":"art"}],"7":[{"r":"his","f":1,"min":90,"t":"Chile antes de Chile","oa":"Historia OA 1 · OA 2 · OA 21","obj":"Explicar cómo los primeros habitantes poblaron el actual territorio chileno y se adaptaron a medios muy distintos, y organizar los equipos.","ini":[15,["Muestra una foto de una momia Chinchorro y otra de Monte Verde. Pregunta: <i>¿Cuántos años creen que tienen?</i>"]],"des":[60,["Mini clase sobre el poblamiento de América y la adaptación al medio.","Forma seis equipos: Monte Verde (hace unos 14.500 años, Los Lagos), cultura Chinchorro (Arica), pueblo diaguita (Norte Chico), el Inca en Chile (Qhapaq Ñan y pucarás), pueblos canoeros del extremo sur y Rapa Nui.","Contrato de equipo (Guía 2)."]],"cie":[15,["Cada equipo formula su pregunta de investigación."]],"rec":["Imágenes de los sitios","Guía 2"],"ev":"<p>Formativa: pregunta de investigación pertinente.</p>"},{"r":"his","f":1,"min":90,"t":"Investigar un sitio arqueológico","oa":"Historia OA 1 · OA 2 · OA 14 · OA 21","obj":"Obtener información de fuentes arqueológicas e históricas sobre el sitio o pueblo del equipo, y su relación con el medio.","ini":[15,["Explica cómo trabaja la arqueología: qué se puede saber de un objeto y qué no."]],"des":[60,["Cada equipo investiga con el dossier: cómo obtenían alimento, cómo construían, qué tecnología usaban y cómo transformaron su medio.","Completan la Guía 1 con al menos tres fuentes, incluida una de un museo o institución."]],"cie":[15,["Cada equipo comparte un dato que cambió lo que creían."]],"rec":["Dossier por sitio","Guía 1"],"ev":"<p>Formativa con la Guía 1.</p>"},{"r":"len","f":1,"min":90,"t":"Investigar y sintetizar","oa":"Lengua y Literatura OA 24 · OA 25","obj":"Delimitar el tema, evaluar la confiabilidad de las fuentes y sintetizar las ideas principales de la investigación.","ini":[15,["Analiza dos fuentes sobre un mismo sitio: una académica y una de divulgación. ¿En qué se diferencian?"]],"des":[60,["<b>Delimitar (15 min).</b> Cada equipo convierte su tema en una pregunta que se pueda responder en la cédula. De «la cultura Chinchorro» a «¿Por qué los Chinchorro momificaban a sus muertos y qué nos dice eso de cómo vivían junto al mar?».","<b>Evaluar fuentes (20 min).</b> Para cada fuente del dossier: ¿quién la publica (museo, universidad, blog)?, ¿cuándo?, ¿cita a quién investigó el sitio? Marcan confiable o dudosa en la tabla de la Guía 1.","<b>Sintetizar (25 min).</b> Cada integrante resume un texto en tres ideas con palabras propias. El equipo las ordena en un organizador: lugar, modo de vida, tecnología, relación con el medio, legado.<span class=\"di\">Si no lo puedes explicar sin mirar el texto, todavía no lo sintetizaste.</span>"]],"cie":[15,["Revisión de la Guía 1 con la lista de cotejo."]],"rec":["Guía 1","Dossier"],"ev":"<p>Lista de cotejo de la Guía 1.</p>"},{"r":"mat","f":2,"min":90,"t":"Escala: proporciones directas","oa":"Matemática OA 8","obj":"Usar la proporcionalidad directa para construir figuras y edificaciones del diorama a escala.","ini":[15,["Pregunta: <i>Si una persona mide 160 cm y en el diorama mide 8 cm, ¿cuánto medirá una ruka de 4 m?</i>"]],"des":[60,["Construyen una tabla de valores real–diorama con la escala 1:20 y la grafican.","Cada equipo calcula las medidas de sus elementos a escala (personas, viviendas, canoas, moai) en la Guía 5."]],"cie":[15,["Explican por qué la tabla forma una línea recta que pasa por el origen."]],"rec":["Guía 5","Calculadoras","Papel milimetrado"],"ev":"<p>Formativa: medidas a escala correctas en la Guía 5.</p>"},{"r":"art","f":2,"min":90,"t":"Interpretar el patrimonio y bocetar","oa":"Artes Visuales OA 4 · OA 2","obj":"Interpretar manifestaciones patrimoniales del pueblo estudiado y diseñar el diorama con materiales sustentables.","ini":[15,["Observan cerámica diaguita, arte rupestre y moai: materialidad, lenguaje visual y propósito."]],"des":[60,["Cada equipo diseña su diorama en la Guía 5: escena, materiales sustentables, colores y formas inspiradas en el patrimonio."]],"cie":[15,["Galería de bocetos y comentarios."]],"rec":["Imágenes patrimoniales","Guía 5"],"ev":"<p>Formativa: boceto aprobado.</p>"},{"r":"tec","f":2,"min":45,"t":"Un museo para todas las personas","oa":"Tecnología OA 1 · OA 5","obj":"Identificar necesidades de los visitantes del museo (niños pequeños, personas con discapacidad visual, adultos mayores) que se pueden resolver con tecnología.","ini":[10,["Pregunta: <i>¿Quién podría tener dificultades para recorrer nuestro museo?</i>"]],"des":[25,["Analizan soluciones existentes en museos (audioguías, textos en braille o letra grande, rampas, alturas).","Cada equipo elige una necesidad: audioguía con código QR, cédula en letra grande o una versión para niños pequeños."]],"cie":[10,["Registran la necesidad y la solución elegida."]],"rec":["Fotos de soluciones de accesibilidad en museos"],"ev":"<p>Formativa: necesidad bien identificada.</p>","alt":"len"},{"r":"art","f":3,"min":90,"t":"Construcción con materiales sustentables","oa":"Artes Visuales OA 2","obj":"Construir el diorama con materiales sustentables, aplicando la escala calculada.","ini":[10,["Revisión del plan y seguridad."]],"des":[70,["<b>Fondo y relieve (25 min).</b> Pintan el paisaje del sitio en el fondo de la caja: el desierto costero de Arica, el bosque húmedo de Monte Verde, los valles diaguitas, los canales australes o la costa de Rapa Nui. Modelan el relieve con papel y cartón reciclados.","<b>Construcciones a escala (30 min).</b> Construyen viviendas, embarcaciones, moai o caminos con las medidas calculadas en Matemática (escala 1:20), usando palitos, fibras naturales, cartón y arcilla.","<b>Figuras y detalles (15 min).</b> Personas a escala realizando una actividad que explique la adaptación al medio: pescar, cultivar, tejer, navegar."]],"cie":[10,["Foto de avance."]],"rec":["Cajas","Materiales reciclados y naturales"],"ev":"<p>Formativa con la rúbrica, criterio construcción.</p>"},{"r":"tec","f":3,"min":90,"t":"La solución: audioguías y accesibilidad","oa":"Tecnología OA 2 · OA 4","obj":"Diseñar e implementar la solución de accesibilidad, comunicándola con herramientas TIC.","ini":[10,["Muestra cómo se graba un audio con un celular y se convierte en un código QR."]],"des":[70,["Cada equipo graba la audioguía de su diorama (1 minuto) y crea el QR, o prepara la cédula en letra grande o la versión para niños.","El curso además graba las audioguías de las salas de 1.° y 2.° básico, si esos cursos lo piden."]],"cie":[10,["Prueban la solución con otro equipo."]],"rec":["Celulares o tablets del colegio","Generador de QR","Impresora"],"ev":"<p>Formativa: la solución funciona.</p>","nota":"<p>Las audioguías se guardan en una cuenta del colegio, no en cuentas personales de los estudiantes.</p>"},{"r":"len","f":3,"min":90,"t":"La cédula: un texto expositivo","oa":"Lengua y Literatura OA 13 · OA 15","obj":"Escribir y revisar un texto expositivo breve para la cédula, con presentación clara del tema y cierre.","ini":[15,["Analiza una cédula de museo real: tema, desarrollo y cierre."]],"des":[60,["<b>Planificar (15 min).</b> Definen destinatario (estudiantes de 1.° a 8.° y familias) y la idea que el visitante debe llevarse en un minuto.","<b>Escribir (25 min).</b> Presentación del tema, dos párrafos de desarrollo (cómo vivían y cómo se adaptaron a su medio) y un cierre que conecte con hoy. Entre 100 y 120 palabras, con la fuente.","<b>Revisar (20 min).</b> Intercambian con otro equipo y aplican la pauta de la Guía 6: oraciones de menos de dos líneas, palabras técnicas explicadas, ortografía y puntuación."]],"cie":[15,["Versión final."]],"rec":["Guía 6"],"ev":"<p>Cédula final con la pauta.</p>"},{"r":"his","f":3,"min":45,"t":"Curaduría: el pueblo y su medio","oa":"Historia OA 22","obj":"Evaluar si el diorama explica la relación entre el pueblo y su medio, y los impactos mutuos.","ini":[10,["Pregunta: <i>¿Qué aprendemos de cómo estos pueblos cuidaron o transformaron su medio?</i>"]],"des":[25,["<b>Lista de verificación (15 min).</b> ¿Se entiende de qué vivían? ¿Aparece el medio (mar, río, bosque, desierto)? ¿Se ve una tecnología o forma de adaptación? ¿Hay elementos de otra época?","<b>Impacto mutuo (10 min).</b> Cada equipo agrega a su cédula una línea sobre cómo el pueblo transformó su medio o cómo el medio limitó su vida."]],"cie":[10,["Cada equipo agrega un elemento si falta."]],"rec":["Dioramas","Lista de verificación"],"ev":"<p>Formativa.</p>"},{"r":"len","f":4,"min":45,"t":"Ensayo de la exposición","oa":"Lengua y Literatura OA 22 · OA 23","obj":"Exponer ante una audiencia con información fidedigna, volumen, velocidad y dicción adecuados.","ini":[10,["Modela una exposición de dos minutos."]],"des":[25,["<b>Rondas (20 min).</b> En pares de equipos, cada uno expone dos minutos frente a su diorama sin leer y responde una pregunta. El otro equipo completa la Guía 9: claridad, volumen, velocidad, dicción e información fidedigna.","<b>Ajustes (5 min).</b> Cada expositor anota dos mejoras concretas en su guion."]],"cie":[10,["Ajustes."]],"rec":["Guías 7 y 9"],"ev":"<p>Formativa.</p>"},{"r":"tec","f":4,"min":45,"t":"Evaluamos la solución","oa":"Tecnología OA 3","obj":"Evaluar la solución de accesibilidad con criterios propios y técnicos y proponer mejoras.","ini":[10,["Presenta los criterios: funciona, se entiende, la usaron los visitantes."]],"des":[25,["Prueban las audioguías con estudiantes de otro curso y registran resultados."]],"cie":[10,["Proponen mejoras."]],"rec":["Audioguías y QR"],"ev":"<p>Evaluación de la solución.</p>","alt":"len"},{"r":"his","f":4,"min":90,"t":"Inauguración y reflexión","oa":"Historia OA 15 · OA 16","obj":"Presentar el diorama y reflexionar sobre el legado de los primeros pueblos en la cultura actual.","ini":[15,["Montaje y turnos."]],"des":[60,["Los guías reciben a los visitantes en la sala «Antes de Chile» por turnos de 20 minutos; quienes no guían recorren el museo con su pasaporte.","Para los cursos de 1.° y 2.°, ofrecen la versión para niños pequeños o la audioguía.","Registra con la lista de observación quién expone sin leer y quién responde preguntas (insumo para la rúbrica)."]],"cie":[15,["Reflexión escrita (Guía 10)."]],"rec":["Sala montada","Guía 10"],"ev":"<p>Sumativa con la rúbrica común.</p>"}],"8":[{"r":"his","f":1,"min":90,"t":"La Colonia en Chile","oa":"Historia OA 8 · OA 11 · OA 12 · OA 13","obj":"Caracterizar la sociedad colonial chilena y organizar los equipos de la sala «Colonia y frontera».","ini":[15,["Muestra un plano de Santiago colonial y una foto actual de la Plaza de Armas. Pregunta qué cambió y qué sigue igual."]],"des":[60,["Mini clase sobre la sociedad colonial: ciudad, Iglesia, hacienda, frontera.","Forma seis equipos: la Plaza de Armas de Santiago, la iglesia de San Francisco, la hacienda colonial, los fuertes de Valdivia, el Parlamento de Quilín (1641) y las misiones jesuitas de Chiloé.","Contrato de equipo (Guía 2)."]],"cie":[15,["Explica el rol especial del curso: <b>8.° básico es el equipo curador del museo de todo el colegio</b>."]],"rec":["Plano de Santiago colonial","Guía 2"],"ev":"<p>Formativa.</p>"},{"r":"his","f":1,"min":90,"t":"Investigar con dos miradas","oa":"Historia OA 11 · OA 12 · OA 17","obj":"Investigar el tema del equipo contrastando la mirada española, mestiza y mapuche o indígena.","ini":[15,["Lee dos fragmentos sobre la frontera: un cronista español y una fuente sobre la mirada mapuche."]],"des":[60,["<b>Las fuentes (25 min).</b> Cada equipo lee en su dossier una fuente española o colonial (crónica, acta, carta) y una que muestre la mirada indígena, mestiza o de los trabajadores (estudio actual, relato mapuche, testimonio).","<b>Comparar (20 min).</b> En la Guía 1, parte D: quién escribe, qué destaca, qué omite, en qué coinciden y en qué difieren.","<b>Decidir (15 min).</b> Escriben en una oración qué mirada se verá en el diorama además de la oficial y cómo la mostrarán (un personaje, un objeto, un cartel)."]],"cie":[15,["Cada equipo comparte en qué difieren las miradas."]],"rec":["Dossier","Guía 1"],"ev":"<p>Formativa con la Guía 1.</p>"},{"r":"len","f":1,"min":90,"t":"Fuentes y síntesis","oa":"Lengua y Literatura OA 25 · OA 26","obj":"Evaluar la confiabilidad de las fuentes, registrarlas y sintetizar las ideas principales.","ini":[15,["Analiza una fuente con errores evidentes y una confiable."]],"des":[60,["<b>Confiabilidad (20 min).</b> Evalúan cada fuente del dossier: autor, fecha, propósito y si registra de dónde saca su información. Las dudosas se descartan o se contrastan.","<b>Síntesis (25 min).</b> Cada integrante sintetiza una fuente en tres ideas propias; el equipo las ordena en un esquema causa–consecuencia.","<b>Registro (15 min).</b> Completan el registro de fuentes de la Guía 1 con el formato acordado por el curso."]],"cie":[15,["Lista de cotejo."]],"rec":["Guía 1"],"ev":"<p>Lista de cotejo de la Guía 1.</p>"},{"r":"art","f":2,"min":90,"t":"Patrimonio colonial y boceto","oa":"Artes Visuales OA 4","obj":"Analizar manifestaciones patrimoniales coloniales según su contexto, materialidad y propósito, y diseñar el diorama.","ini":[15,["Observan la iglesia de San Francisco, una iglesia de Chiloé y objetos coloniales."]],"des":[60,["<b>Analizar (25 min).</b> En equipos, analizan una obra o edificio colonial: contexto (quién la encargó y para qué), materialidad (adobe, madera, piedra, tejido), lenguaje visual y propósito expresivo.","<b>Bocetar (35 min).</b> Dibujan la escena del diorama de frente y desde arriba en la Guía 5, eligiendo materiales sustentables y una paleta inspirada en el patrimonio analizado."]],"cie":[15,["Galería de bocetos."]],"rec":["Imágenes patrimoniales","Guía 5"],"ev":"<p>Formativa: boceto aprobado.</p>"},{"r":"art","f":3,"min":90,"t":"Curadores del museo","oa":"Artes Visuales OA 6","obj":"Analizar cómo se monta un museo (espacio, recorrido, público) y diseñar el recorrido del museo del colegio.","ini":[15,["Comparen dos museos: cómo guían al visitante, cómo usan la luz y los textos."]],"des":[60,["Con el plano del lugar de la inauguración, el curso diseña el recorrido de todas las salas en orden cronológico (Guía 11).","Definen la señalética: nombre de cada sala, flechas, número de sala."]],"cie":[15,["Presentan el plan a la coordinación del proyecto."]],"rec":["Plano del lugar","Guía 11: Plan de curaduría"],"ev":"<p>Plan de curaduría evaluado con la Guía 11.</p>"},{"r":"mat","f":2,"min":90,"t":"Cajas y vitrinas: área y volumen","oa":"Matemática OA 11","obj":"Calcular el área de superficie y el volumen de prismas para fabricar las cajas de los dioramas y las bases de exhibición.","ini":[15,["Pregunta: <i>¿Cuánto cartón necesitamos para una base de exhibición de 40 × 30 × 20 cm?</i>"]],"des":[60,["Cada equipo dibuja la red de su caja y de su base, calcula el área y el volumen y corta según su cálculo."]],"cie":[15,["Comparan el cálculo con el material usado."]],"rec":["Cartón","Reglas","Calculadoras"],"ev":"<p>Formativa: área y volumen correctos.</p>"},{"r":"tec","f":2,"min":45,"t":"La señalética del museo","oa":"Tecnología OA 1 · OA 5","obj":"Identificar qué necesitan los visitantes para orientarse y examinar soluciones de señalética existentes.","ini":[10,["Muestra señalética de museos y estaciones de metro."]],"des":[25,["Definen qué señales necesita el museo y para quién."]],"cie":[10,["Registran la necesidad."]],"rec":["Fotos de señalética"],"ev":"<p>Formativa.</p>","alt":"art"},{"r":"art","f":3,"min":90,"t":"Construcción del diorama","oa":"Artes Visuales OA 2","obj":"Construir el diorama con materiales sustentables, papeles y textiles.","ini":[10,["Seguridad y organización."]],"des":[70,["<b>Estructura (25 min).</b> Construyen la caja con las medidas calculadas en Matemática y el relieve o la planta del lugar (plaza, iglesia, casa patronal, fuerte, cancha del parlamento, capilla).","<b>Edificaciones y figuras (30 min).</b> Construyen las edificaciones con cartón, palitos y papeles; modelan figuras que muestren a los distintos grupos de la sociedad colonial.","<b>Textiles y detalles (15 min).</b> Agregan tejidos, techos de paja o tejuela y los elementos que muestran la segunda mirada acordada en Historia."]],"cie":[10,["Foto de avance."]],"rec":["Cajas","Materiales reciclados, papeles, textiles"],"ev":"<p>Formativa con la rúbrica.</p>"},{"r":"tec","f":3,"min":90,"t":"Fabricamos la señalética","oa":"Tecnología OA 2 · OA 4","obj":"Diseñar y crear la señalética del museo con criterios de eficiencia y sustentabilidad.","ini":[10,["Revisa el plan de curaduría."]],"des":[70,["Diseñan en computador o a mano los carteles de cada sala, las flechas del recorrido y el plano para la entrada."]],"cie":[10,["Prueban la legibilidad a tres metros."]],"rec":["Computador e impresora o cartulinas","Plan de curaduría"],"ev":"<p>Formativa.</p>"},{"r":"len","f":3,"min":90,"t":"Texto expositivo de la cédula","oa":"Lengua y Literatura OA 14 · OA 16","obj":"Escribir un texto expositivo para la cédula, con información de distintas fuentes y un cierre coherente.","ini":[15,["Analiza una cédula real."]],"des":[60,["<b>Planificar (15 min).</b> Propósito, destinatario y la idea central que debe llevarse el visitante.","<b>Escribir (25 min).</b> Presentación del tema, desarrollo con información de al menos dos fuentes y cierre coherente. Unas 120 palabras.","<b>Revisar y reescribir (20 min).</b> Con la pauta de la Guía 6 y el comentario de otro equipo, corrigen cohesión, ortografía y puntuación (punto, coma, raya y dos puntos)."]],"cie":[15,["Versión final."]],"rec":["Guía 6"],"ev":"<p>Cédula final con la pauta.</p>"},{"r":"his","f":3,"min":45,"t":"Revisión: ¿se escuchan las dos miradas?","oa":"Historia OA 12","obj":"Revisar que el diorama represente la convivencia y el conflicto entre españoles, mestizos y pueblos indígenas.","ini":[10,["Pregunta: <i>¿Quién aparece en nuestro diorama y quién falta?</i>"]],"des":[25,["<b>Lista de verificación (15 min).</b> ¿Aparecen españoles, mestizos e indígenas? ¿Se muestra convivencia y conflicto? ¿Hay elementos de otra época?","<b>Corrección (10 min).</b> Cada equipo agrega o cambia al menos un elemento para que la segunda mirada se vea sin tener que leer la cédula."]],"cie":[10,["Comparten los cambios."]],"rec":["Dioramas"],"ev":"<p>Formativa.</p>"},{"r":"art","f":4,"min":45,"t":"Montaje del museo","oa":"Artes Visuales OA 6","obj":"Montar el museo completo siguiendo el plan de curaduría, coordinando a los demás cursos.","ini":[10,["Reparte tareas: señalética, recorrido, ubicación de salas, iluminación."]],"des":[25,["<b>Señalética (10 min).</b> Instalan los carteles de cada sala y las flechas del recorrido según el plan de curaduría.","<b>Recepción de salas (15 min).</b> Cada pareja de 8.° recibe a un curso y lo ayuda a ubicar su sala en el lugar acordado, cuidando alturas y paso libre."]],"cie":[10,["Recorrido de prueba."]],"rec":["Señalética","Plan de curaduría"],"ev":"<p>Formativa.</p>"},{"r":"len","f":4,"min":45,"t":"Ensayo de la exposición","oa":"Lengua y Literatura OA 23 · OA 24","obj":"Exponer con claridad, progresión temática y dicción adecuada.","ini":[10,["Modela una exposición."]],"des":[25,["<b>Rondas (20 min).</b> En pares de equipos, cada uno expone dos minutos con progresión temática, sin leer, y responde una pregunta. El otro equipo completa la Guía 9.","<b>Ajustes (5 min).</b> Cada expositor anota dos mejoras y el equipo decide quién guía en cada turno."]],"cie":[10,["Ajustes."]],"rec":["Guías 7 y 9"],"ev":"<p>Formativa.</p>"},{"r":"tec","f":4,"min":45,"t":"Evaluamos la señalética","oa":"Tecnología OA 3","obj":"Evaluar la señalética con los visitantes y proponer mejoras al proceso y al producto.","ini":[10,["Criterios: se ve, se entiende, guía el recorrido."]],"des":[25,["Observan a los primeros visitantes y anotan dónde se pierden."]],"cie":[10,["Proponen mejoras."]],"rec":["Pauta de observación"],"ev":"<p>Evaluación de la señalética.</p>","alt":"art"},{"r":"his","f":4,"min":90,"t":"Inauguración y reflexión","oa":"Historia OA 16 · OA 19","obj":"Guiar la sala «Colonia y frontera» y reflexionar sobre cómo la sociedad colonial desembocó en la Independencia.","ini":[15,["Montaje final y turnos."]],"des":[60,["Los guías explican la sala «Colonia y frontera» por turnos; el resto del curso orienta a los visitantes en el recorrido general.","Al cerrar, el equipo curador recoge las respuestas del mural «¿Qué Chile falta?».","Registra con la lista de observación quién expone sin leer y quién responde preguntas (insumo para la rúbrica)."]],"cie":[15,["Reflexión escrita (Guía 10)."]],"rec":["Museo montado","Guía 10"],"ev":"<p>Sumativa con la rúbrica común.</p>"}]},"capacidades":[["Pintar y modelar",[2,2,2,2,2,2,2,2]],["Construir maquetas",[0,1,1,2,2,2,2,2]],["Investigar en fuentes",[0,1,1,1,2,2,2,2]],["Escribir la cédula",[0,1,1,2,2,2,2,2]],["Explicar al público",[0,1,1,2,2,2,2,2]],["Cantar o actuar",[2,2,2,2,2,2,2,2]],["Organizar el museo",[0,0,0,0,1,1,2,2]]]};
